/* Keep authoring helpers local when loaded as a classic browser script. */
(function () {
'use strict';
const D=globalThis.RA.D;
const Q=(prompt,answer,wrong1,wrong2,explain,errorType='meaning')=>({prompt,answer,options:[answer,wrong1,wrong2],explain,errorType});
const M=(wrong,right,reason,errorType='meaning')=>({errorType,wrong,right,reason});
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:w==='mm'?'NIST SI length unit reference: https://www.nist.gov/pml/owm/si-units-length':'Etymonline: https://www.etymonline.com/word/'+w.toLowerCase().replaceAll(' ','-')});
const P=(w,origin,c,m,qs)=>{const senseMap={miracle:[1,1,2,1],mire:[1,2,1,2],mirror:[1,2,3,4],misdeed:[1,2,1,2],miserable:[1,2,3,1],misfortune:[1,2,1,2],misgiving:[1,2,1,2],mishap:[1,2,1,2],mislead:[1,2,1,2],mismatch:[1,2,1,2],misprint:[1,2,1,2],miss:[1,2,3,4],missile:[1,2,1,2],missing:[1,2,1,2],mission:[1,2,3,4],missionary:[1,2,1,2],mist:[1,2,3,1],mistake:[1,2,3,1],mistress:[1,2,3,1],misunderstand:[1,2,1,2],mitigate:[1,2,1,2],mix:[1,2,3,4],moan:[1,2,3,1],moat:[1,2,1,2],mobile:[1,2,3,1],mobility:[1,2,1,2],mobilize:[1,2,1,2],mock:[1,2,3,2]};return D(w,{etymology:E(origin,w),contexts:Array.isArray(c)?c:[c],mistakes:[m],quiz:qs.map((q,i)=>({...q,id:w+'.q'+(i+1),senseId:w+'.s'+(senseMap[w]?.[i]||1),type:'辨义与用法'}))});};
P('miracle','From Old French miracle and Latin miraculum, “a wonder,” from mirari, “to wonder.”', [C('miracle.s1','医学突破','The vaccine was hailed as a medical miracle after it sharply reduced deaths from the previously deadly infection.','这种疫苗大幅降低了此前致命感染造成的死亡率，因此被誉为医学奇迹。','The vaccine was hailed / as a medical miracle / after it sharply reduced deaths / from the previously deadly infection.','miracle 作名词，指极不寻常、仿佛奇迹般的事件或结果。','显著减少死亡是令人惊叹的积极结果。')], M('The report called the ordinary daily sunrise a miracle even though it was fully expected and routine.','The report called the unexpected recovery from the fatal illness a miracle.','日常且可预料的日出不符合“奇迹般事件”的语境。'), [Q('Why was the vaccine called a medical miracle?','It sharply reduced deaths from a deadly infection.','It was sold in a new bottle.','It was used to measure the weather.','miracle 指令人惊叹的结果；疫苗显著减少死亡。'),Q('A miracle is usually?','an extraordinary and welcome event','a routine appointment','a small piece of glass','miracle 常指非凡、出乎意料的好事。'),Q('Which event best fits “a miracle”?','A lost child was found unharmed after days in the storm.','The bus arrived at its published time.','The shop opened as scheduled.','失踪儿童在风暴后安然获救是令人惊叹的事。'),Q('What does “by some miracle” suggest?','Something unlikely happened successfully.','A plan followed its normal routine.','A person measured a distance.','该表达强调结果出乎意料、仿佛奇迹。')]);
P('miraculous','Formed from miracle with the adjective suffix -ous; it describes something extraordinarily surprising or seemingly caused by a miracle.',C('miraculous.s1','康复描述','After weeks with no improvement, the climber made a miraculous recovery and walked out of the hospital unaided.','数周没有好转后，登山者奇迹般地康复，没靠人搀扶就走出了医院。','After weeks with no improvement / the climber made / a miraculous recovery / and walked out of the hospital unaided.','miraculous 作形容词，修饰 recovery，表示好得出奇、近乎奇迹。','此前长期无改善而后独立出院，构成惊人的转变。'),M('The doctor described the gradual, expected recovery as miraculous even though nothing unusual had happened.','The doctor described the sudden recovery from a grave injury as miraculous.','平常且可预料的康复不支持 miraculous 的强烈语气。'),[Q('A miraculous recovery is?','an extraordinarily surprising recovery','a recovery that is always slow and expected','a medical appointment','miraculous 强调康复出奇地好。'),Q('What happened after weeks without improvement?','The climber recovered and left unaided.','The climber became a hospital doctor.','The climber returned to the mountain immediately.','登山者意外康复并独立出院。'),Q('Which noun naturally follows miraculous?','escape','measurement unit','menu price only','miraculous escape 是自然搭配，表示奇迹般脱险。','collocation'),Q('Miraculous is formed from miracle plus?','-ous','-ment','-less','形容词后缀 -ous 表示“具有……性质的”。','word-formation')]);
P('mirage','From French mirage, related to se mirer, “to be reflected”; the word names an optical illusion often seen in hot air.',C('mirage.s1','沙漠光学现象','The hikers thought a lake lay ahead, but the shimmering water was only a mirage caused by layers of hot air.','徒步者以为前方有湖，但闪烁的水面只是由热空气层造成的海市蜃楼。','The hikers thought / a lake lay ahead / but the shimmering water / was only a mirage caused by layers of hot air.','mirage 作名词，指由大气折射造成、看似真实却不存在的影像。','看似湖水的影像实际上由热空气造成。'),M('The hikers drank from the mirage because it was a real lake that had been tested and mapped.','The hikers approached what looked like a lake, but it vanished as the mirage shifted with the heat.','mirage 是视觉假象，不能当作真实水源。'),[Q('What appeared ahead of the hikers?','A false image of a lake.','A marked trail sign.','A real river with a bridge.','他们看到的是热空气造成的假湖影像。'),Q('A mirage is an?','optical illusion','underground spring','accurate map','mirage 指视觉假象。'),Q('Where are mirages often seen?','Over hot ground or in deserts.','Inside a sealed freezer.','Under a printed label.','热空气层常造成海市蜃楼。'),Q('Why did the apparent lake shimmer?','Layers of hot air bent the light.','The hikers had built a reservoir.','The water was being stirred.','例句解释影像来自热空气导致的光学现象。')]);
P('mire','Probably from Scandinavian roots meaning “bog”; as a noun it means deep wet mud or a difficult situation, and as a verb it means to trap or bog down.',[C('mire.s1','泥泞路面','The delivery van sank into the mire beside the flooded track, and its wheels spun without moving it forward.','送货车陷进被水淹道路旁的泥潭，车轮空转却无法前进。','The delivery van sank / into the mire / beside the flooded track / and its wheels spun without moving it forward.','mire.s1 作名词可指深而湿的泥，也可比喻难以摆脱的困境。','车轮陷入湿泥无法前进。'),C('mire.s2','陷入困局','Repeated delays mired the building project in legal disputes and left the opening date uncertain.','一再延期使这项建筑工程陷入法律纠纷，开业日期也无法确定。','Repeated delays mired the building project / in legal disputes / and left the opening date / uncertain.','mire.s2 作动词，常用 mire someone/something in，表示使陷入困境。','工程被延误和纠纷拖住。')],M('The van was mired in the road, so its wheels rolled freely and it drove away at once.','The van was mired in deep mud, and a tow truck had to pull it free.','若车轮能自由行驶并立即离开，就没有陷入泥潭。'),[Q('The van sank into the mire means it sank into?','deep wet mud','a dry paved floor','a meeting room','mire.s1 可指深湿泥潭。'),Q('The project was mired in disputes means it was?','stuck in difficult disputes','finished ahead of schedule','moved to a new city','mire.s2 比喻项目陷入难以摆脱的困境。'),Q('What did the van’s wheels do?','They spun without moving the van.','They lifted the van into the air.','They stopped existing.','车轮空转，车辆无法前进。'),Q('Which construction means “陷入法律纠纷”?','be mired in legal disputes','be mirrored by legal disputes','be medicated on legal disputes','mire in + 困境表示陷入其中。','collocation')]);
P('mirror','From Old French mireoir, from mirer, “to look at,” ultimately related to Latin mirari, “to wonder”; it can name a reflecting object or mean reflect, represent, or closely match.',[C('mirror.s1','日常物品','She checked the back of her jacket in the mirror before leaving for the interview.','她出门参加面试前，在镜子里检查了夹克后面。','She checked / the back of her jacket / in the mirror / before leaving for the interview.','mirror.s1 是反射影像的镜子。','在镜中检查衣服体现实物义。'),C('mirror.s2','现实写照','The novel is a mirror of the social divisions that shaped the city during that decade.','这部小说是那个年代塑造这座城市的社会分化的真实写照。','The novel is / a mirror of the social divisions / that shaped the city / during that decade.','mirror.s2 作比喻名词，指反映现实的事物或写照。','小说反映社会分化。'),C('mirror.s3','反映数据','The survey results mirror the sharp rise in rent reported by residents across the city.','调查结果反映了全城居民报告的租金大幅上涨。','The survey results mirror / the sharp rise in rent / reported by residents / across the city.','mirror.s3 作及物动词，表示反映或映照出真实情况。','结果呈现居民报告的租金上涨。'),C('mirror.s4','相似对应','The two versions of the contract mirror each other, apart from the dates and the names of the signatories.','两份合同除日期和签署人姓名外彼此对应一致。','The two versions of the contract mirror each other / apart from the dates / and the names / of the signatories.','mirror.s4 作动词，表示与另一事物非常相似或对应。','合同版本除少数信息外相互匹配。')],M('The mirror showed no reflection, so it accurately mirrored the room behind the viewer.','The mirror reflected the viewer, while the survey mirrored the wider public’s concerns.','没有反射影像就不能说镜子映出了房间。'),[Q('Where did she check her jacket?','In a reflective glass mirror.','In a muddy mire.','On a city survey.','mirror.s1 指反射影像的镜子。'),Q('The novel is a mirror of social divisions means it?','reflects those divisions','is made of glass','caused the divisions to disappear','mirror.s2 比喻为现实写照。'),Q('Survey results mirror a rise in rent means they?','reflect or show that increase','hide all evidence of it','set the rent themselves','mirror.s3 表示调查结果反映租金上涨。'),Q('Two contract versions mirror each other when they?','closely correspond apart from stated differences','are placed in front of a mirror','use unrelated terms throughout','mirror.s4 表示彼此相似、对应。')]);
P('misappropriate','From mis- “wrongly” plus appropriate, “to take or assign”; it means to use money or property dishonestly or for an unauthorized purpose.',C('misappropriate.s1','资金挪用','The treasurer was dismissed after auditors found that she had misappropriated donations for personal travel.','审计人员发现财务主管挪用捐款支付个人旅行费用后，她被解雇了。','The treasurer was dismissed / after auditors found / that she had misappropriated donations / for personal travel.','misappropriate 作及物动词，指不诚实或未经授权地使用受托资金、财产。','捐款被拿去支付私人旅行费用。'),M('The charity misappropriated no funds because it spent every donation exactly as the donors had authorized.','The charity misappropriated funds when its director diverted donations to a private account.','按捐赠者授权用途使用资金不构成挪用。'),[Q('To misappropriate donations is to?','use them dishonestly or without permission','record them accurately for the charity','return them to the donors as promised','misappropriate 指不当挪用资金或财物。'),Q('Why was the treasurer dismissed?','She used donations for personal travel.','She completed the annual audit.','She asked donors how to allocate money.','她把捐款用于私人旅行。'),Q('Which item is most likely misappropriated?','Funds entrusted to an employee for a project','A personal lunch bought with personal money','A public report copied with permission','misappropriate 通常涉及受托资金或财产。'),Q('Which pattern is grammatical?','misappropriate public funds','misappropriate to public funds','misappropriate on public funds','该动词直接接被挪用的资金作宾语。','grammar')]);
P('misbehave','Formed from mis- “badly or wrongly” and behave; it means to behave badly, especially by breaking rules.',C('misbehave.s1','课堂纪律','The pupils were warned not to misbehave during the museum tour because other visitors were listening to the guide.','学生们被提醒参观博物馆时不要捣乱，因为其他游客正在听讲解。','The pupils were warned / not to misbehave / during the museum tour / because other visitors were listening to the guide.','misbehave 作不及物动词，指行为不当或不守规则。','在讲解时捣乱会影响其他游客。'),M('The children misbehaved by following every rule, listening quietly, and helping the guide.','The children misbehaved by shouting in the gallery and touching objects marked “do not touch.”','安静守规矩并协助讲解员不是行为不当。'),[Q('Pupils who misbehave during a tour?','break rules or act badly','carefully follow every instruction','guide the museum staff','misbehave 指行为不当。'),Q('Why were the pupils warned?','Other visitors were listening to the guide.','The museum had no exhibits.','The guide wanted them to leave school.','提醒是为了不影响正在听讲解的人。'),Q('Which action is misbehaviour in a gallery?','Shouting and touching a protected object.','Reading the exhibit label quietly.','Following the guide’s directions.','大声喧哗并触碰禁触展品属于捣乱。'),Q('Misbehave is usually used?','without a direct object','with “a rule” as its direct object','only as an adjective','misbehave 本身是不及物动词。','grammar')]);
P('miscalculate','Formed from mis- “wrongly” and calculate; it means to calculate incorrectly or to judge a situation badly.',C('miscalculate.s1','预算估算','The contractor miscalculated the amount of tile needed, so the crew had to pause while more was delivered.','承包商算错了所需瓷砖数量，施工队只得停工等待补货。','The contractor miscalculated / the amount of tile needed / so the crew had to pause / while more was delivered.','miscalculate 可指算错数值，也可指错误估计时间、成本或形势。','所需材料数量被算错。'),M('The contractor miscalculated the order perfectly and received exactly the required amount, with no error.','The contractor miscalculated the tile order and had to wait for an additional delivery.','完全准确的订单不是误算。'),[Q('Why did the crew have to pause?','Too little tile had been ordered after a wrong calculation.','The tiles had been installed ahead of schedule.','The contractor closed the road for a race.','承包商低估了所需瓷砖数量。'),Q('To miscalculate a cost is to?','work it out incorrectly','pay it exactly on time','cancel the project legally','miscalculate 指计算或估计错误。'),Q('Which decision shows a miscalculation of time?','Assuming a two-hour journey takes twenty minutes','Checking the timetable before leaving','Allowing an extra hour for traffic','把两小时路程误估为二十分钟是错误估时。'),Q('What prefix contributes “wrongly” in miscalculate?','mis-','pre-','re-','mis- 在此构词中表示错误地。','word-formation')]);
P('miscarriage','Formed from mis- “wrongly or badly” and carry, with -age; it names a pregnancy loss before the fetus can survive independently, and more broadly a failure of a process or justice.',[C('miscarriage.s1','妊娠医学','The clinic offered follow-up care and counselling after the patient experienced a miscarriage early in pregnancy.','患者在孕早期流产后，诊所为她提供了后续护理和心理咨询。','The clinic offered follow-up care / and counselling / after the patient experienced a miscarriage / early in pregnancy.','miscarriage.s1 指妊娠在胎儿可存活前终止，也称流产。','例句明确是孕早期妊娠丢失。')],M('The record called a full-term birth with a healthy surviving baby a miscarriage.','The record noted that the pregnancy ended in a miscarriage before the fetus could survive.','健康足月分娩不是 miscarriage。'),[Q('In the medical sense, miscarriage is?','the loss of a pregnancy before the fetus can survive','a routine prenatal appointment','a child’s first day at school','miscarriage 的医学义是胎儿可存活前的妊娠丢失。'),Q('What support did the clinic provide?','follow-up care and counselling','a new employment contract','a tour of a medieval hall','诊所提供后续护理和咨询。'),Q('Which phrase is natural?','experience a miscarriage','miscarry a medication to someone','miscarriage on a pregnancy','常说 experience or have a miscarriage。','collocation'),Q('The broader phrase “a miscarriage of justice” means?','a serious failure of the legal process','a successful and fair trial','a medical treatment plan','该固定表达指司法不公或司法失败。')]);
P('miscellaneous','From Latin miscellaneus, “mixed,” related to miscere, “to mix”; it describes a collection of different kinds of things.',C('miscellaneous.s1','杂项档案','The folder contains miscellaneous receipts, spare keys, and notes that do not belong to any single project.','文件夹里装着杂项收据、备用钥匙和不属于任何单一项目的便条。','The folder contains / miscellaneous receipts, spare keys, and notes / that do not belong / to any single project.','miscellaneous 作形容词，表示由不同种类的东西混在一起。','文件内容种类不同且无单一归类。'),M('The clerk filed every receipt under one clearly defined category but labelled the folder miscellaneous.','The clerk put unrelated receipts and notes into a miscellaneous folder.','整齐归入一个明确类别的内容不算杂项集合。'),[Q('Miscellaneous receipts are receipts?','of various kinds without one category','all from one named project','that have already been destroyed','miscellaneous 指不同类别混杂的。'),Q('What was in the folder?','Receipts, spare keys, and assorted notes.','Only the final signed contract.','A single medical prescription.','文件夹里有几种不同物品。'),Q('Which title fits a page with unrelated notices?','Miscellaneous notices','One detailed weather forecast','The project’s single invoice','不同主题的通知可归入 miscellaneous。'),Q('Miscellaneous is closest in meaning to?','assorted','identical','essentially empty','assorted 表示各种各样的。')]);
P('mischance','From mis- “bad” and chance in the older sense of fortune or outcome; it means an unlucky event or accident.',C('mischance.s1','意外延误','By mischance, the only copy of the signed form was soaked when a bottle leaked in the courier’s bag.','不巧的是，快递员包里的瓶子漏水，把唯一一份签字表格浸湿了。','By mischance / the only copy of the signed form was soaked / when a bottle leaked / in the courier’s bag.','mischance 作名词，指由偶然造成的不幸或意外。','瓶子意外漏水导致重要文件受损。'),M('The team called the planned, carefully scheduled delivery a mischance even though nothing went wrong.','The team called the accidental loss of the package a mischance.','按计划顺利完成的配送不是不幸意外。'),[Q('By mischance means?','by an unlucky accident','with careful planning','for a medical purpose','mischance 指偶然发生的不幸。'),Q('What damaged the signed form?','A leaking bottle in the courier’s bag.','A deliberate photocopy.','A scheduled meeting.','包中的瓶子意外漏水。'),Q('A mischance is most likely?','an unfortunate event','a guaranteed success','a routine appointment','该词指厄运或不测。'),Q('Which sentence uses mischance naturally?','By mischance, the last train was cancelled during the storm.','By mischance, the train arrived exactly as planned.','She mischance the ticket carefully.','风暴中末班车取消是意外的不幸。','usage')]);
P('mischief','From Old French meschief, “trouble, harm, misfortune,” ultimately built from elements meaning “badly” and “come to an end”; it means playful trouble or harmful wrongdoing.',C('mischief.s1','轻微恶作剧','The twins got into mischief by swapping the labels on the harmless jars in their science project.','这对双胞胎在科学项目中调换无害罐子的标签，淘气地惹了点麻烦。','The twins got into mischief / by swapping the labels / on the harmless jars / in their science project.','mischief 可指淘气或轻微恶作剧，常用于 get into mischief。','调换标签是顽皮但不严重的捣乱。'),M('The children called the harmless prank mischief, then described it as a deliberate violent attack that injured several people.','The children called their harmless label-swapping prank mischief.','严重暴力伤害超出通常的轻微淘气义。'),[Q('The twins got into mischief by?','swapping labels on harmless jars','carefully following the project rules','repairing a broken window','他们调换标签，做了个小恶作剧。'),Q('Mischief can mean?','playful trouble or wrongdoing','a formal medical diagnosis','a type of city','mischief 可指淘气、捣乱或伤害。'),Q('Which phrase is natural?','get into mischief','do a mischief at','mischief oneself into','get into mischief 是常见搭配。','collocation'),Q('The example suggests the prank was?','minor and harmless','a serious assault','a planned bank theft','例句明确说罐子无害，行为是轻微恶作剧。')]);
P('mischievous','Formed from mischief plus -ous; it describes someone playfully causing trouble or a look that suggests such an intention.',C('mischievous.s1','顽皮举止','With a mischievous grin, Nia hid the birthday card behind the vase and waited for her brother to find it.','妮娅带着顽皮的笑容把生日卡藏在花瓶后，等着弟弟发现。','With a mischievous grin / Nia hid the birthday card / behind the vase / and waited for her brother to find it.','mischievous 作形容词，可形容爱恶作剧的人或带有淘气意味的表情。','藏卡片并等弟弟发现，表现俏皮恶作剧。'),M('Nia gave a mischievous grin while explaining that she had never played a joke or caused any playful trouble.','Nia gave a mischievous grin as she hid the card for her brother to discover.','语境中的藏卡片恶作剧与否认任何顽皮行为不一致。'),[Q('Nia’s mischievous grin suggests she?','has planned a playful trick','is seriously ill','has forgotten how to smile','mischievous grin 暗示淘气或恶作剧的念头。'),Q('What did Nia hide?','A birthday card.','A medicine bottle in a hospital.','The museum’s stone arch.','她把生日卡藏在花瓶后。'),Q('A mischievous child is likely to?','play harmless tricks','obey every rule without exception','repair a road professionally','mischievous 描写爱淘气、恶作剧的人。'),Q('Which spelling is correct?','mischievous','mischevious','mischievious','标准拼写是 mischievous。','spelling')]);
P('misconceive','Formed from mis- “wrongly” and conceive; it means to form a mistaken idea about something.',C('misconceive.s1','计划理解','The committee misconceived the proposal as a plan to close the clinic, although it only recommended changing its opening hours.','委员会误以为提案要关闭诊所，实际上它只建议调整开放时间。','The committee misconceived the proposal / as a plan to close the clinic / although it only recommended / changing its opening hours.','misconceive 作及物动词，指对事实、计划或某人的意思形成错误看法。','委员会把调整时间误解成关闭诊所。'),M('The committee misconceived the proposal correctly after reading that it changed hours but did not close the clinic.','The committee misconceived the proposal as a closure plan when it only changed clinic hours.','准确理解提案内容不叫 misconceive。'),[Q('The committee misconceived the proposal as?','a plan to close the clinic','a request to repaint the town hall','a medical prescription','他们错误地把调整时间理解为关闭诊所。'),Q('To misconceive an idea is to?','form a false understanding of it','explain it accurately','forget its spelling only','misconceive 表示形成错误概念。'),Q('What did the proposal actually recommend?','Changing the clinic’s opening hours.','Closing the clinic permanently.','Moving the clinic overseas.','提案只建议调整开放时间。'),Q('Which sentence uses misconceive correctly?','Readers may misconceive the warning as a ban.','Readers may misconceive to the warning as a ban.','Readers may misconceive the warning for understand.','可说 misconceive something as something。','grammar')]);
P('misconception','From mis- “wrongly” and conception, a forming of an idea; it means a mistaken belief or understanding.',C('misconception.s1','科学误解','A common misconception is that seasons occur because Earth is much closer to the Sun in summer.','一种常见误解是，季节变化是因为夏天的地球离太阳近得多。','A common misconception / is that seasons occur / because Earth is much closer to the Sun / in summer.','misconception 是对事实形成的错误观念，常与 common 搭配。','句中观点把季节成因错误归结为日地距离。'),M('The textbook called the proven explanation of Earth’s axial tilt a misconception, even though the evidence confirmed it.','The textbook corrected the misconception that seasons are caused mainly by Earth’s changing distance from the Sun.','有证据支持的解释不是错误观念；例句中的距离说法才是误解。'),[Q('The misconception in the example is that seasons happen because?','Earth is much closer to the Sun in summer','Earth stops rotating in winter','the Moon changes its colour','例句指出这是关于季节成因的错误观念。'),Q('A misconception is?','a mistaken belief or understanding','a carefully measured distance','a type of medical treatment','misconception 指错误想法或误解。'),Q('Which adjective commonly modifies misconception?','common','metallic only','melted','常见搭配是 common misconception。','collocation'),Q('What does the passage imply about the belief?','It is wrong.','It is confirmed by the explanation.','It is a seasonal forecast.','misconception 本身即表示错误观念。')]);
P('misconduct','From mis- “wrongly” and conduct, “behaviour”; it means improper or dishonest behaviour, especially in a professional role.',C('misconduct.s1','职业违规','The review found serious research misconduct because the scientist had altered data and concealed the original results.','调查认定存在严重科研不端，因为科学家篡改数据并隐瞒原始结果。','The review found / serious research misconduct / because the scientist had altered data / and concealed the original results.','misconduct 作名词，指不当行为，尤指职务或职业中的违规。','篡改并隐瞒研究数据属于科研不端。'),M('The panel ruled that the honest, fully documented study was misconduct despite finding no rule violation.','The panel ruled that falsifying research data was serious misconduct.','诚实且符合规范的研究不能仅凭标签称为不端。'),[Q('Why was the research called misconduct?','The scientist altered data and hid the originals.','The scientist shared all results transparently.','The panel scheduled a meeting.','篡改和隐瞒数据构成不端行为。'),Q('Misconduct is especially associated with?','improper behaviour in a role or profession','a playful birthday surprise','an accurate scientific finding','misconduct 常指工作或职务中的违规行为。'),Q('Research misconduct can include?','fabricating or altering evidence','checking data carefully','citing the source of a result','捏造或篡改证据属于科研不端。'),Q('Which phrase is standard?','professional misconduct','professional misbehave','misconducting of professional','professional misconduct 是自然名词搭配。','collocation')]);
P('misdeed','From mis- “wrongly” and deed, “an act”; it means a bad or wrongful act, with the legal seriousness depending on context.',[C('misdeed.s1','违法行为','The prosecutor listed the theft and fraud as misdeeds for which the defendant could be tried under criminal law.','检察官把盗窃和诈骗列为被告可能依法受审的违法行为。','The prosecutor listed / the theft and fraud / as misdeeds / for which the defendant could be tried under criminal law.','misdeed.s1 可指违法或犯罪行为。','盗窃和诈骗可能按刑法起诉。'),C('misdeed.s2','不端之举','He admitted the minor misdeed of taking credit for a colleague’s idea and apologised at the next team meeting.','他承认了把同事的想法据为己有这一轻微不端行为，并在下一次团队会议上道歉。','He admitted / the minor misdeed / of taking credit for a colleague’s idea / and apologised at the next team meeting.','misdeed.s2 泛指可耻或不道德的行为，不一定是犯罪。','冒领同事创意不道德，但未必构成犯罪。')],M('She called a harmless, permitted act a serious misdeed although it violated no rule and harmed nobody.','She called the deliberate theft of a colleague’s work a misdeed and apologised.','无害且获准的行为不符合不端行为的含义。'),[Q('The prosecutor’s misdeeds were?','theft and fraud','honest reporting and repayment','a routine team meeting','此处 misdeed 指可依法起诉的犯罪行为。'),Q('Taking credit for a colleague’s idea was described as?','a minor wrongful act','a formally approved reward','a criminal sentence already served','把同事创意据为己有是不端行为。'),Q('Does every misdeed have to be a crime?','No; it can also mean an immoral or shameful act.','Yes; it only means a felony.','Yes; it only means a traffic ticket.','misdeed 也可泛指不道德行为。'),Q('Which word part contributes the sense “wrongly”?','mis-','de-','-ed','mis- 表示做错或不当。','word-formation')]);
P('misdemeanor','From mis- plus Middle English demenure, “conduct”; in US law a misdemeanor is a less serious criminal offence than a felony.',C('misdemeanor.s1','美国法律','The judge treated the first-time shoplifting charge as a misdemeanor, carrying a possible fine rather than a lengthy prison term.','法官将初犯的商店盗窃指控按轻罪处理，可能处以罚款，而非长期监禁。','The judge treated / the first-time shoplifting charge / as a misdemeanor / carrying a possible fine rather than a lengthy prison term.','misdemeanor 在美国法律中指低于 felony 的较轻刑事犯罪。','句中与罚款和长期监禁对比，体现较轻罪行。'),M('The court labelled the offence a misdemeanor but sentenced the defendant under the jurisdiction’s definition of its most serious felony.','The court classified the minor offence as a misdemeanor and considered a fine.','把它称作轻罪却按最严重重罪处理，分类与处罚相冲突。'),[Q('In US law, a misdemeanor is generally?','a less serious offence than a felony','a civil marriage contract','the most serious crime category','misdemeanor 的严重程度通常低于 felony。'),Q('What penalty was possible in the example?','A fine.','A guaranteed life sentence.','A ban on all court hearings.','例句提到可能罚款而非长期监禁。'),Q('Which legal system does the entry specifically mention?','The United States.','Every country with identical law.','Only medieval England.','该词释义明确标为美国法律用语。'),Q('Which spelling is the US form?','misdemeanor','misdemeanour','misdemenor','美式拼写是 misdemeanor。','spelling')]);
P('misdirect','From mis- “wrongly” and direct; it means to send someone or something in the wrong direction or to give incorrect guidance.',C('misdirect.s1','错误路线','The receptionist misdirected the visitors to the east entrance, so they missed the presentation’s opening remarks.','接待员把访客指错到东门，他们因此错过了演讲开场。','The receptionist misdirected the visitors / to the east entrance / so they missed / the presentation’s opening remarks.','misdirect 作动词，表示把人引向错误方向或给出错误指引。','访客被带到不对的入口。'),M('The receptionist misdirected visitors by giving them the correct entrance and a clear map.','The receptionist misdirected visitors by sending them to a closed entrance on the opposite side.','给出正确路线不是 misdirect。'),[Q('The visitors were misdirected to?','the wrong entrance','the correct presentation room','a nearby café they had requested','他们被指到了错误入口。'),Q('To misdirect a person is to?','send or guide them the wrong way','give them accurate directions','cancel their travel ticket','misdirect 指错误引导。'),Q('What did the visitors miss?','The opening remarks.','The entire building.','A scheduled flight abroad.','走错入口让他们错过开场发言。'),Q('Which phrase is natural?','misdirect the audience','misdirect to the audience the','misdirect with audience from','misdirect 可直接接被引错的人作宾语。','grammar')]);
P('miser','From Latin miser, “wretched or unhappy”; the modern noun describes someone who hoards money and is unwilling to spend it.',C('miser.s1','吝啬性格','Although wealthy, the miser refused to heat his cold house and kept every coin locked away.','尽管很富有，这个守财奴仍不肯给冰冷的房子供暖，把每枚硬币都锁起来。','Although wealthy / the miser refused to heat his cold house / and kept every coin / locked away.','miser 作名词，指为了积攒财富而极不愿花钱的人。','他有钱却不愿用于基本舒适，符合守财奴义。'),M('The novel called the woman a miser because she spent freely on others and gave away her entire fortune.','The novel called the woman a miser because she hoarded her wealth and avoided ordinary spending.','乐于花钱并捐尽财富与守财奴特征相反。'),[Q('A miser is someone who?','hoards money and hates spending it','spends all income immediately','works as a medical researcher','miser 指吝啬、囤积钱财的人。'),Q('What did the wealthy miser refuse to do?','Heat his cold house.','Count any coins.','Keep money in a bank.','他不肯花钱取暖。'),Q('Which behaviour best fits miser?','Saving wealth while living needlessly poorly','Giving away all savings without hesitation','Paying every bill promptly and generously','为保留财富而过分节省符合 miser 的含义。'),Q('Miser is related historically to a Latin word meaning?','wretched or unhappy','sea and maiden','middle of the day','miser 来自拉丁语 miser，原义“不幸、悲惨”。','word-formation')]);
P('miserable','From Old French miserable and Latin miserabilis, “pitiable”; it describes great unhappiness, very unpleasant conditions, or an extremely small amount.',[C('miserable.s1','个人感受','After the long delay and missed connection, the exhausted travellers felt miserable in the cold station.','长时间延误又错过接驳后，疲惫的旅客在寒冷的车站里感到十分难受。','After the long delay and missed connection / the exhausted travellers felt miserable / in the cold station.','miserable.s1 描写人的痛苦、不快乐或不舒服。','旅客疲惫、受冻且行程受阻。'),C('miserable.s2','条件恶劣','The crew worked in miserable conditions, with no clean water and only a leaking roof for shelter.','工作人员在恶劣条件下工作，没有干净饮水，能遮蔽的只有漏雨屋顶。','The crew worked / in miserable conditions / with no clean water / and only a leaking roof for shelter.','miserable.s2 也可修饰令人难受、低劣或凄惨的状况。','缺水和漏雨构成极差的工作条件。'),C('miserable.s3','数量微薄','The shop offered a miserable refund of two dollars for a suitcase that had cost hundreds.','商店只肯为价值数百美元的行李箱退两美元，金额少得可怜。','The shop offered / a miserable refund of two dollars / for a suitcase / that had cost hundreds.','miserable.s3 可形容数量或程度少得可怜。','与数百美元价格相比，两美元退款极少。')],M('The workers called the clean, safe, well-equipped room miserable although it had every comfort they needed.','The workers called the cold, leaking shelter miserable because it lacked basic comforts.','舒适齐全的房间不符合 miserable 的负面评价。'),[Q('The travellers felt miserable because they were?','exhausted, delayed, and cold','celebrating a successful connection','working in a warm hotel','miserable.s1 表示痛苦、不快乐或不舒服。'),Q('Miserable conditions are?','very unpleasant or poor','luxurious and comfortable','exactly average in every way','miserable.s2 描述恶劣条件。'),Q('A miserable refund of two dollars is?','pitifully small','larger than the original price','a full repayment','miserable.s3 可表示数量少得可怜。'),Q('What was wrong with the crew’s shelter?','It had a leaking roof and no clean water.','It had too many comfortable rooms.','It was located near a station.','例句列出的条件很差。')]);
P('miserly','From miser plus -ly; as an adjective it means excessively unwilling to spend or give money.',C('miserly.s1','过度吝啬','The landlord was so miserly that he refused to replace a broken stair light, even after tenants offered to split the cost.','房东吝啬到连坏掉的楼梯灯也不肯更换，尽管租户愿意分摊费用。','The landlord was so miserly / that he refused to replace a broken stair light / even after tenants offered / to split the cost.','miserly 作形容词，指过分不愿花钱或给予。','租户愿分担而房东仍不肯出钱，体现过度吝啬。'),M('The biography called the donor miserly even though she gave away most of her fortune and paid every worker generously.','The biography described the donor as miserly because she hoarded wealth and refused reasonable expenses.','慷慨捐赠并善待员工与 miserly 相反。'),[Q('A miserly landlord is unwilling to?','spend money even on a needed repair','collect any rent at all','keep records of the property','miserly 指花钱过分小气。'),Q('Why was the stair light still broken?','The landlord refused to pay for its replacement.','The tenants rejected a free replacement.','The building had no stairs.','房东不愿承担合理维修费用。'),Q('Miserly is closest to?','stingy','generous','carefree','stingy 表示吝啬，语义接近 miserly。'),Q('Miserly is formed from miser plus?','-ly','-ment','-ous','miserly 由 miser 加 -ly 构成形容词。','word-formation')]);
P('misery','From Old French miserie and Latin miseria, “wretchedness”; it means great unhappiness, pain, or suffering.',C('misery.s1','长期苦难','Years of untreated pain had brought the patient so much misery that even simple daily tasks became difficult.','多年未治疗的疼痛给患者带来巨大痛苦，连简单的日常事务都变得困难。','Years of untreated pain / had brought the patient / so much misery / that even simple daily tasks became difficult.','misery 是强烈的不快乐、痛苦或苦难，常用于 bring someone misery。','慢性疼痛严重影响生活。'),M('The report described the comfortable holiday as misery, although the visitors felt relaxed and delighted throughout.','The report described years of untreated pain as misery because it caused constant suffering.','轻松愉快的假期与 misery 的痛苦义相反。'),[Q('The patient experienced misery because of?','years of untreated pain','a short comfortable holiday','a successful refund','misery 指强烈痛苦或不幸。'),Q('What became difficult for the patient?','Simple daily tasks.','The patient’s medical diagnosis.','The spelling of the word pain.','长期疼痛使日常任务难以完成。'),Q('Which phrase uses misery naturally?','live in misery','misery a prescription to','a misery of medicine someone','live in misery 是自然表达。','collocation'),Q('Misery is closest in meaning to?','suffering','celebration','measurement','misery 指痛苦、苦难。')]);
P('misfortune','From mis- “bad” and fortune in the sense of chance or luck; it means bad luck or an unlucky event.',[C('misfortune.s1','运气不佳','Through misfortune, both job offers were withdrawn on the same day, leaving Amira without work.','倒霉的是，两份工作邀请在同一天都被撤回，阿米拉因此失去了工作机会。','Through misfortune / both job offers were withdrawn on the same day / leaving Amira / without work.','misfortune.s1 可泛指坏运气或不幸的境遇。','同时失去两份工作机会是坏运气。'),C('misfortune.s2','不幸事件','The flood was a misfortune for the village, destroying the bridge and cutting off the road to the clinic.','洪水给村庄带来灾祸，摧毁桥梁并切断了通往诊所的道路。','The flood was / a misfortune for the village / destroying the bridge / and cutting off the road to the clinic.','misfortune.s2 也可指一件具体的不幸事件。','洪水是造成损失的具体灾祸。')],M('The village called the newly repaired bridge a misfortune because it safely reopened the road and caused no damage.','The village called the flood a misfortune because it destroyed the bridge and isolated residents.','安全修好的桥不是造成损失的不幸事件。'),[Q('Amira’s misfortune was that?','both job offers were withdrawn','she received two offers','she began a new job','misfortune.s1 指坏运气或不幸处境。'),Q('In the second example, what was the misfortune?','A flood that destroyed the bridge.','A successful road repair.','A new clinic opening.','misfortune.s2 指具体的不幸事件。'),Q('Misfortune is made from mis- plus?','fortune','form','future','mis- 与 fortune 组合表示坏运气。','word-formation'),Q('Which sentence uses misfortune naturally?','By misfortune, the shipment was lost in the storm.','By misfortune, the shipment arrived safely as planned.','She misfortune the shipment yesterday.','风暴中货物丢失是具体的不幸。','usage')]);
P('misgiving','From misgive, with mis- “badly” and give in an older sense of “suggest”; as a noun it means a doubt or uneasy feeling about a decision.',[C('misgiving.s1','决策疑虑','The engineer had misgivings about opening the bridge before the final safety tests were complete.','最后的安全测试尚未完成，工程师对提前开放桥梁心存疑虑。','The engineer had misgivings / about opening the bridge / before the final safety tests / were complete.','misgiving.s1 指对某事可能不妥的怀疑或保留意见。','工程师担心提前开放不安全。'),C('misgiving.s2','不安情绪','Despite her misgivings, Lena boarded the small boat as dark clouds gathered over the lake.','尽管心里不安，莱娜还是在湖面乌云聚集时登上了小船。','Despite her misgivings / Lena boarded the small boat / as dark clouds gathered / over the lake.','misgiving.s2 可指做冒险之事前的担忧、不安。','乌云和小船使她感到不安。')],M('The engineer had misgivings about the unsafe bridge, so she felt completely certain that no danger existed.','The engineer had misgivings about the bridge because safety tests were unfinished.','对安全有疑虑与确信毫无危险互相矛盾。'),[Q('The engineer’s misgivings concerned?','opening the bridge before tests were finished','closing the clinic for renovation','the colour of the safety vest','misgiving.s1 是对提前开放的疑虑。'),Q('Despite her misgivings, Lena?','boarded the boat while clouds gathered','cancelled the trip before leaving home','repaired the bridge herself','misgiving.s2 指冒险前的不安。'),Q('Misgivings are often?','doubts or uneasy feelings','confirmed measurements','formal invitations','misgivings 指疑虑、担忧。'),Q('Which collocation is natural?','have misgivings about a plan','have misgivings with a plan at','do misgivings a plan','常说 have misgivings about something。','collocation')]);
P('misguided','Formed from mis- “wrongly” and guided; it describes a person or action led by a mistaken idea, even when the intention is good.',C('misguided.s1','好心办错事','The misguided volunteer released the rescued birds before their injuries had healed, hoping to help them return to the wild.','这名志愿者出于好心，在获救的鸟伤口痊愈前就放飞了它们。','The misguided volunteer released the rescued birds / before their injuries had healed / hoping / to help them return to the wild.','misguided 常指受错误判断引导的做法，未必出于恶意。','志愿者本意是帮助鸟类，但判断时机错误。'),M('The report called the plan misguided even though it was based on accurate evidence and achieved its stated purpose safely.','The report called the plan misguided because it relied on a false assumption despite good intentions.','判断准确且安全达成目的，不支持 misguided 的评价。'),[Q('Why was the volunteer’s action misguided?','The birds were released before their injuries healed.','The volunteer refused to help any birds.','The birds had already migrated south.','时机判断错误，反而可能伤害鸟类。'),Q('Misguided actions may be?','well-intended but based on a mistaken idea','deliberately cruel in every case','guaranteed to succeed','misguided 强调错误判断，不必然有恶意。'),Q('Which phrase is natural?','a misguided attempt to help','a misguided of attempt to help','misguided help attemptingly','misguided attempt 是自然搭配。','collocation'),Q('The prefix mis- contributes the idea of?','being wrong or mistaken','being before something','being together','mis- 在此表示错误。','word-formation')]);
P('mishandle','Formed from mis- “badly” and handle; it means to manage, operate, or treat something clumsily or wrongly.',C('mishandle.s1','资料处置','The clerk mishandled the confidential files by leaving them on an unlocked desk in a public corridor.','职员把机密文件留在公共走廊里未上锁的桌子上，处理方式很不当。','The clerk mishandled the confidential files / by leaving them / on an unlocked desk / in a public corridor.','mishandle 可指操作失误、管理不善或粗暴对待。','未妥善保护机密文件属于错误处置。'),M('The clerk mishandled the files by locking them in the secure cabinet and recording every transfer correctly.','The clerk mishandled the files by leaving them unsecured where visitors could read them.','妥善上锁并准确登记不是处置不当。'),[Q('How did the clerk mishandle the files?','By leaving them unsecured in a public corridor.','By locking them in a secure cabinet.','By shredding them under an approved policy.','机密文件暴露在公共场所，处置不当。'),Q('To mishandle equipment may mean to?','operate it incorrectly','use it exactly as instructed','repair it successfully','mishandle 指操作或处理不当。'),Q('Which example is mishandling a person?','Grabbing a patient roughly during transfer','Explaining a procedure gently','Asking for consent before treatment','粗暴对待患者属于 mishandle 的行为义。'),Q('Mishandle is formed from handle plus?','mis-','-hood','-ship','mis- 表示处理得不好或错误。','word-formation')]);
P('mishap','From mis- “bad” and hap, an older word for chance or luck; it means a minor accident or an unlucky event.',[C('mishap.s1','小意外','A minor mishap with the paint can left a blue streak on the floor, but no one was hurt.','油漆罐出了点小意外，在地板上留下蓝色痕迹，不过没人受伤。','A minor mishap with the paint can / left a blue streak / on the floor / but no one was hurt.','mishap.s1 常指损害较小的事故。','油漆洒出造成轻微麻烦，无人受伤。'),C('mishap.s2','不幸遭遇','The cancellation of the last ferry was an unfortunate mishap that stranded the research team overnight.','末班渡轮取消是不幸的意外，使研究团队滞留了一夜。','The cancellation of the last ferry / was an unfortunate mishap / that stranded the research team / overnight.','mishap.s2 泛指造成麻烦的不幸事件。','取消渡轮导致团队滞留。')],M('The newspaper called a fatal explosion with dozens of injuries a minor mishap and reported that nobody was harmed.','The newspaper called the small paint spill a minor mishap because it caused little harm.','造成大量伤亡的爆炸不能被描述成轻微小事故。'),[Q('What was the minor mishap with the paint can?','It left a blue streak on the floor.','It caused a building collapse.','It delayed the ferry for a week.','mishap.s1 指损害较小的意外。'),Q('The ferry cancellation was a mishap because it?','stranded the team overnight','delivered the team early','repaired the research boat','mishap.s2 指带来麻烦的不幸事件。'),Q('A mishap is usually?','an accident or unlucky event','a deliberate award ceremony','a form of medicine','mishap 表示事故或不幸遭遇。'),Q('Which phrase is common?','a minor mishap','a minor mishapful','mishaply minor','minor mishap 是常见搭配。','collocation')]);
P('mishear','Formed from mis- “wrongly” and hear; it means to hear something incorrectly.',C('mishear.s1','听错姓名','I misheard the station announcement and got off one stop early because I thought it named my destination.','我听错了车站广播，以为报的是目的地，于是提前一站下了车。','I misheard the station announcement / and got off one stop early / because I thought / it named my destination.','mishear 是 hear 的不规则动词，指听到的内容与实际说的不同。','听错广播造成提前下车。'),M('I misheard the announcement perfectly, so I repeated every word exactly as the speaker said it.','I misheard the announcement and got off at the wrong station.','准确听清并复述不是 mishear。'),[Q('Why did the passenger get off early?','They misheard the station announcement.','They missed the train on purpose.','The station had no announcements.','听错目的地广播导致提前下车。'),Q('To mishear someone is to?','hear their words incorrectly','refuse to listen at all','repeat their words accurately','mishear 指误听。'),Q('What is the simple past of mishear?','misheard','misheared','mishears','mishear 的过去式是 misheard。','verb-form'),Q('Which sentence uses mishear correctly?','I misheard “fifteen” as “fifty.”','I misheard to the station yesterday.','I misheard him clearly and repeated nothing wrong.','把 fifteen 听成 fifty 是误听。','usage')]);
P('misinterpret','Formed from mis- “wrongly” and interpret; it means to understand or explain something incorrectly.',C('misinterpret.s1','误读语气','Readers may misinterpret the brief reply as anger, although the writer intended it only as a quick confirmation.','读者可能把简短回复误解为生气，尽管写信人只想快速确认。','Readers may misinterpret the brief reply / as anger / although the writer intended it / only as a quick confirmation.','misinterpret 常用于 misinterpret something as something，表示错误理解或解释。','简短不等于生气，读者可能误判语气。'),M('The reader misinterpreted the reply accurately and understood the writer’s intended meaning without error.','The reader misinterpreted the brief reply as anger although it was intended as confirmation.','准确理解不属于 misinterpret。'),[Q('Readers may misinterpret the brief reply as?','anger','a full legal contract','a medical diagnosis','他们可能把简短回复错误理解为生气。'),Q('What did the writer intend?','A quick confirmation.','An angry complaint.','A cancellation of the project.','作者的真实意图只是快速确认。'),Q('To misinterpret a message is to?','understand it incorrectly','translate it perfectly','send it to the wrong address only','misinterpret 指错误理解或解释。'),Q('Which pattern is correct?','misinterpret a short reply as anger','misinterpret as anger a short reply to','misinterpret with a short reply','常用结构是 misinterpret A as B。','grammar')]);
P('misjudge','Formed from mis- “wrongly” and judge; it means to form an incorrect opinion or estimate about someone or something.',C('misjudge.s1','判断时间','We misjudged the traffic and left too late, so the team arrived after the client presentation had begun.','我们误判了交通状况，出发太晚，团队到达时客户演示已经开始。','We misjudged the traffic / and left too late / so the team arrived / after the client presentation had begun.','misjudge 可指对人、事或时间作出错误判断。','低估路况导致迟到。'),M('The team misjudged the traffic correctly, left with ample time, and arrived well before the presentation.','The team misjudged the traffic and arrived after the meeting had started.','正确判断并提前到达不属于 misjudge。'),[Q('Why did the team arrive late?','They misjudged the traffic and left too late.','They arrived before leaving.','The client cancelled the presentation.','团队错误估计了交通时间。'),Q('To misjudge someone is to?','form a wrong opinion about them','measure them with a ruler','meet them for the first time','misjudge 指形成错误判断。'),Q('Which action shows misjudging a situation?','Assuming a storm is harmless despite official evacuation warnings','Checking the forecast and leaving early','Asking an expert to review uncertain evidence','忽略警报并错误估计风暴风险属于判断失误。'),Q('Misjudge is formed from judge plus?','mis-','-ful','-er','mis- 表示错误地判断。','word-formation')]);
P('mislead','From Old English mislædan, “lead astray,” built from mis- “wrongly” and lead; it means to cause a false belief or lead someone the wrong way.',[C('mislead.s1','错误信息','The advertisement misled customers by claiming that the supplement had been proven to cure the disease.','广告声称这种补充剂已被证明能治愈疾病，误导了顾客。','The advertisement misled customers / by claiming / that the supplement had been proven / to cure the disease.','mislead.s1 指使人相信不真实的信息，常带故意误导意味。','广告作出无根据的治愈承诺。'),C('mislead.s2','带错方向','The damaged sign misled hikers onto a closed trail that ended at a steep drop.','损坏的路标把徒步者引上了一条已封闭的小径，尽头是陡坡。','The damaged sign misled hikers / onto a closed trail / that ended / at a steep drop.','mislead.s2 也可指把人带到错误方向或道路。','路标把徒步者引错路线。')],M('The label misled shoppers by accurately listing every ingredient and making no unsupported health claim.','The label misled shoppers by hiding an allergen and falsely calling the product safe for everyone.','完整准确且没有虚假声称的标签不构成误导。'),[Q('How did the advertisement mislead customers?','It made an unproven cure claim.','It listed a verified price only.','It told customers to read the evidence.','mislead.s1 指造成错误信念。'),Q('Where did the sign lead the hikers?','Onto a closed and dangerous trail.','Back to the visitor centre safely.','To a marked picnic area.','mislead.s2 指把人带错方向。'),Q('What does misleading information do?','It encourages a false belief.','It guarantees complete accuracy.','It removes every misunderstanding.','误导信息会使人形成错误信念。'),Q('Which pattern is natural?','mislead someone about the risks','mislead to someone the risks','mislead someone for believing','可说 mislead someone about something。','grammar')]);
P('misleading','Formed from mislead plus -ing; it describes information or appearances likely to create a false impression.',C('misleading.s1','数据呈现','The chart was misleading because it began its vertical axis at ninety, making a small change look enormous.','图表具有误导性，因为纵轴从90开始，使微小变化看起来巨大。','The chart was misleading / because it began its vertical axis at ninety / making a small change / look enormous.','misleading 作形容词，指容易使人产生错误印象的。','截断坐标轴夸大了数据变化。'),M('The chart was misleading because it displayed every value on a clearly labelled, proportional scale with no distortion.','The chart was misleading because its truncated axis exaggerated a small change.','准确标度且没有扭曲的图表不具误导性。'),[Q('Why was the chart misleading?','Its vertical axis exaggerated a small change.','It displayed no numbers at all.','It showed a large change at the correct scale.','截断纵轴制造了夸大的视觉印象。'),Q('Misleading information is likely to?','create a false impression','explain every detail clearly','prevent all errors','misleading 指容易导致误解的。'),Q('Which word is formed from misleading?','mislead','melody','meeting','misleading 由 mislead 加 -ing 构成。','word-formation'),Q('Which phrase is natural?','a misleading headline','a misleadingly headline','a headline misleading of','misleading 可作形容词修饰 headline。','grammar')]);
P('mismanage','Formed from mis- “badly” and manage; it means to run or handle an organisation, resource, or situation incompetently.',C('mismanage.s1','资金管理','The board mismanaged the grant by approving unrelated expenses and failing to keep the required records.','董事会批准无关支出且没有保存规定记录，管理这笔拨款不当。','The board mismanaged the grant / by approving unrelated expenses / and failing / to keep the required records.','mismanage 指经营或处置不善，导致资源被浪费或问题恶化。','拨款被用于无关开支且账目缺失。'),M('The board mismanaged the grant by following every restriction, documenting each expense, and meeting all deadlines.','The board mismanaged the grant by spending it on unrelated items and losing the records.','遵守条件并完整记录不是管理不善。'),[Q('How did the board mismanage the grant?','It approved unrelated expenses and lost required records.','It followed every rule and reported costs.','It returned unused funds on time.','董事会未按要求管理拨款。'),Q('To mismanage a company is to?','run it incompetently','manage it effectively','sell it at the right price','mismanage 表示管理不当。'),Q('What might mismanagement cause?','Wasted funds or worsening problems.','Guaranteed savings in every case.','An accurate medical diagnosis.','管理不善可能浪费资源或使问题恶化。'),Q('Which phrase is natural?','mismanage public resources','mismanage about public resources','mismanage to public resources','mismanage 可直接接被管理的对象。','grammar')]);
P('mismatch','From mis- “wrongly” plus match; as a noun it means a poor fit, and as a verb it means to pair things that do not suit each other.',[C('mismatch.s1','技能不相称','The mismatch between the job’s technical demands and his experience became clear during the first week.','这份工作的技术要求与他的经验不相称，在第一周就显露出来。','The mismatch / between the job’s technical demands / and his experience / became clear during the first week.','mismatch.s1 作名词，指两者之间不合适或不相称。','工作要求与经验不匹配。'),C('mismatch.s2','错误配对','The scheduler mismatched the two mentors with trainees whose goals required very different expertise.','排班人员把两位导师错配给了需要不同专长的学员。','The scheduler mismatched the two mentors / with trainees / whose goals required / very different expertise.','mismatch.s2 作动词，表示把不合适的人或物配在一起。','导师专长和学员目标不对应。')],M('The coordinator called the pairing a mismatch even though each mentor’s skills exactly matched the trainee’s needs.','The coordinator found a mismatch because each trainee needed expertise the assigned mentor did not have.','技能完全符合需求时不能称为错配。'),[Q('The mismatch in the first example was between?','job demands and the worker’s experience','two identical job titles','the job site and a lunch menu','mismatch.s1 指两者不相称。'),Q('The scheduler mismatched mentors when they?','paired them with trainees needing different expertise','paired every trainee with a suitable specialist','cancelled the training programme','mismatch.s2 是把不合适的人配在一起。'),Q('Which phrase means “存在技能不匹配”?','There is a mismatch in skills.','There is a matchless of skills.','The skills mismatchfully.','mismatch 可作名词表示不相称。'),Q('Which use makes mismatch a verb?','They mismatched the parts.','The mismatch was obvious.','A mismatch appeared in the data.','mismatched 在句中作动词，表示错配。','grammar')]);
P('misprint','From mis- “wrongly” and print; as a noun it is an error in printed text, and as a verb it means to print something incorrectly.',[C('misprint.s1','出版错误','The first edition contained a misprint in the map caption, placing the river twenty kilometres north of its actual course.','第一版地图说明中有一处印刷错误，把河流标在实际河道以北二十公里处。','The first edition contained / a misprint in the map caption / placing the river / twenty kilometres north of its actual course.','misprint.s1 作名词，指印刷中出现的错误。','地图说明的错误位置是印刷错误。'),C('misprint.s2','印错数字','The printer misprinted the batch number on every label, so the entire shipment had to be recalled.','印刷机把每张标签上的批次号都印错了，因此整批货不得不召回。','The printer misprinted the batch number / on every label / so the entire shipment / had to be recalled.','misprint.s2 作动词，指把文字或数字印错。','批次号被印错。')],M('The proofreader marked a correct, accurately printed caption as a misprint although no letter or number was wrong.','The proofreader found a misprint where the caption gave the wrong river distance.','字母和数字都准确时不能说有印刷错误。'),[Q('The first edition’s misprint was in?','the map caption','the river itself','the shipment’s packing material','misprint.s1 指印刷文本中的错误。'),Q('The printer misprinted the?','batch number on each label','actual river course','shipment after recalling it','misprint.s2 是把批次号印错。'),Q('A misprint is an error made while?','printing text or numbers','measuring a river by boat','writing a private diary by hand only','misprint 指印刷错误。'),Q('Which sentence uses misprint as a verb?','The press misprinted the date.','A misprint appeared in the date.','They corrected the misprint.','misprinted 在此是动词过去式。','grammar')]);
P('misread','Formed from mis- “wrongly” and read; it means to read or understand written signs, a situation, or someone’s intention incorrectly.',C('misread.s1','看错表格','I misread the dosage on the label as ten millilitres instead of one and checked with the pharmacist before taking it.','我把标签上的剂量看成10毫升而不是1毫升，服用前向药剂师确认。','I misread the dosage / on the label as ten millilitres / instead of one / and checked with the pharmacist before taking it.','misread 作动词，过去式和过去分词拼写相同，指读错或理解错。','把1毫升读成10毫升是读错标签。'),M('I misread the label correctly, so I followed its one-millilitre instruction exactly.','I misread the label as ten millilitres, then confirmed the correct one-millilitre dose.','准确照读标签不是 misread。'),[Q('What did the speaker misread?','The dosage on the medicine label.','The pharmacist’s name on a badge.','The date on a bus ticket.','说话者把标签剂量看错了。'),Q('What does misread mean here?','Read or understand incorrectly.','Memorise a page exactly.','Write a new label.','misread 指读错或误解。'),Q('What is the past tense spelling of misread?','misread','misreaded','misrode','misread 的过去式与原形同形，读音不同。','verb-form'),Q('Why did the speaker ask the pharmacist?','The apparent dose seemed ten times larger than one millilitre.','The label had no dosage.','The speaker wanted a bus timetable.','剂量差异很大，因此先核实安全信息。')]);
P('misreading','From misread plus -ing; it names an incorrect reading or interpretation of a text, figure, or situation.',C('misreading.s1','文本解释','The editor corrected a misreading of the poem’s final line, which had been taken as an apology rather than a warning.','编辑纠正了对诗歌末行的误读；那句话被当成道歉，而不是警告。','The editor corrected / a misreading of the poem’s final line / which had been taken / as an apology rather than a warning.','misreading 作名词，指对文字或情境的不正确理解。','编辑指出句意被错误解释。'),M('The editor called it a misreading even though the reader had interpreted the final line exactly as the author explained it.','The editor called it a misreading because the reader took a warning as an apology.','完全符合作者解释的理解不是误读。'),[Q('What was misread in the example?','The poem’s final line.','The editor’s office address.','A medicine dosage.','misreading.s1 指对诗句的误读。'),Q('How did the reader interpret the line incorrectly?','As an apology instead of a warning.','As a warning exactly as intended.','As a measurement of distance.','读者把警告误解成道歉。'),Q('A misreading is?','an incorrect interpretation','a perfectly accurate quotation','a printing machine','misreading 指错误阅读或解释。'),Q('Which phrase is natural?','a misreading of the evidence','a misreading about of the evidence','to do a misreading the evidence','常说 a misreading of something。','collocation')]);
P('misreport','Formed from mis- “wrongly” and report; it means to report facts incorrectly, whether by mistake or deliberately.',C('misreport.s1','数据报道','The bulletin misreported the storm’s arrival time by two hours, so residents began preparations too late.','公告把风暴到达时间报错了两小时，居民因此准备得太晚。','The bulletin misreported / the storm’s arrival time / by two hours / so residents began preparations too late.','misreport 作动词，表示错误报道或上报事实。','时间信息有误导致准备迟缓。'),M('The bulletin misreported the arrival time accurately to the minute and caused no confusion.','The bulletin misreported the arrival time by two hours, delaying residents’ preparations.','准确到分钟的报道不属于 misreport。'),[Q('What did the bulletin misreport?','The storm’s arrival time.','The storm’s colour.','The residents’ home addresses.','公告把风暴到达时间报错了。'),Q('To misreport a fact is to?','report it incorrectly','verify it with several sources','keep it entirely private','misreport 指错误报告事实。'),Q('What consequence followed the wrong report?','Residents prepared too late.','The storm changed direction instantly.','The bulletin was printed in a different colour.','错误时间导致准备延迟。'),Q('Misreport may happen?','by mistake or deliberately','only when facts are correct','only in private conversation','该词既可指无心报错，也可指故意谎报。')]);
P('misrepresent','From mis- “wrongly” and represent; it means to describe, present, or portray something inaccurately or dishonestly.',C('misrepresent.s1','数据歪曲','The company misrepresented its test results by highlighting one success and hiding the many failed trials.','公司只突出一次成功并隐瞒多次失败试验，歪曲了测试结果。','The company misrepresented its test results / by highlighting one success / and hiding / the many failed trials.','misrepresent 指不准确或不诚实地陈述、呈现事实。','选择性隐瞒失败试验造成失实印象。'),M('The company misrepresented its results by publishing every trial, including failures, with a complete explanation.','The company misrepresented its results by omitting most failed trials and claiming consistent success.','完整公开试验结果不属于歪曲呈现。'),[Q('How did the company misrepresent its results?','It highlighted one success and hid many failures.','It published every trial transparently.','It delayed the test until next year.','公司隐瞒失败并突出单次成功。'),Q('To misrepresent evidence is to?','present it inaccurately or dishonestly','summarise it faithfully','store it in a locked cabinet','misrepresent 指歪曲或不实陈述。'),Q('Which action is misrepresentation?','Editing a quote so it appears to say the opposite','Quoting a statement in full context','Correcting a factual typo openly','断章取义改变意思属于歪曲陈述。'),Q('Which phrase is grammatical?','misrepresent the facts','misrepresent about the facts','misrepresent to the facts','misrepresent 直接接所歪曲的内容作宾语。','grammar')]);
P('miss','From Old English missan, “fail to hit, reach, or perceive”; later senses include failing to attend, feeling someone’s absence, and the title Miss.',[C('miss.s1','未击中目标','The archer missed the target by a few centimetres, so the arrow struck the padded wall behind it.','弓箭手差几厘米没射中靶子，箭落在后面的软垫墙上。','The archer missed the target / by a few centimetres / so the arrow struck / the padded wall behind it.','miss.s1 指没有击中、抓住或达到目标。','箭落在靶后而非靶上。'),C('miss.s2','错过班车','Hurry, or we will miss the last bus and have to walk home in the rain.','快点，否则我们会错过末班公交，只能冒雨走回家。','Hurry / or we will miss the last bus / and have to walk home / in the rain.','miss.s2 指迟到而错过交通、活动或机会。','未赶上末班公交。'),C('miss.s3','想念亲友','After moving abroad, he began to miss his sister’s Sunday visits and familiar jokes.','搬到国外后，他开始想念姐姐每周日的探访和熟悉的玩笑。','After moving abroad / he began to miss / his sister’s Sunday visits / and familiar jokes.','miss.s3 作及物动词，表示因人或事物不在身边而感到想念。','他怀念姐姐的探访和玩笑。'),C('miss.s4','称呼用语','Miss Patel will lead the discussion after lunch, so please send your questions to her beforehand.','帕特尔小姐将在午餐后主持讨论，请提前把问题发给她。','Miss Patel will lead the discussion / after lunch / so please send your questions / to her beforehand.','Miss.s4 是置于女性姓名前的称呼，传统上用于未婚女性。','Miss Patel 用作姓名前称呼。')],M('We missed the last bus, meaning we boarded it on time and reached home before the rain began.','We missed the last bus and had to walk home in the rain.','按时乘车不是错过公交。'),[Q('What happened to the archer?','The arrow did not hit the target.','The arrow hit the centre.','The archer missed the bus.','miss.s1 表示未击中目标。'),Q('If you miss the last bus, you?','arrive too late to board it','ride it home as planned','meet its driver for lunch','miss.s2 指因迟到未能乘坐。'),Q('He misses his sister means he?','feels sad because she is away','fails to recognise her name only','wants to cancel her visit','miss.s3 表示想念不在身边的人。'),Q('In “Miss Patel,” Miss is?','a title before a woman’s name','a verb meaning fail to hit','a name for a bus','miss.s4 是女性姓名前的称呼。')]);
P('misshapen','Formed from mis- “wrongly” and shape; it describes something that has an abnormal or unintended shape.',C('misshapen.s1','物品变形','The heat left the plastic lid misshapen, so it no longer fitted securely over the container.','高温使塑料盖变了形，无法再牢固盖住容器。','The heat left the plastic lid misshapen / so it no longer fitted securely / over the container.','misshapen 作形容词，描述形状异常或变形的物体。','塑料盖受热变形而无法贴合。'),M('The potter called the perfectly round bowl misshapen even though every side was symmetrical and smooth.','The potter called the uneven, distorted bowl misshapen.','形状匀称完好的碗不应称为 misshapen。'),[Q('Why was the lid misshapen?','Heat distorted its shape.','It was polished until perfectly round.','It was placed inside a container.','受热导致盖子变形。'),Q('A misshapen object has?','an abnormal or distorted shape','the exact intended shape','no physical form at all','misshapen 指形状异常或变形。'),Q('Which object could be misshapen?','A bent metal frame.','A precisely circular new plate.','A printed receipt.','弯曲变形的金属框符合 misshapen。'),Q('Which prefix marks an incorrect shape?','mis-','over-','anti-','mis- 在 misshapen 中表示形状不正常。','word-formation')]);
P('missile','From French missile and Latin missilis, “that may be thrown,” related to mittere, “send”; it can mean a guided rocket weapon or an object thrown to hit something.',[C('missile.s1','制导武器','The defence report said the missile changed course in flight after its guidance system locked onto the target.','防务报告称，导弹的制导系统锁定目标后，它在飞行中改变了航向。','The defence report said / the missile changed course in flight / after its guidance system / locked onto the target.','missile.s1 指能够飞向目标的制导火箭武器。','制导系统使武器锁定目标并调整航向。'),C('missile.s2','投掷物','During the snowball fight, a soft snowball became an unlikely missile aimed at the empty cardboard box.','打雪仗时，一个软雪球成了投向空纸箱的投掷物。','During the snowball fight / a soft snowball became / an unlikely missile / aimed at the empty cardboard box.','missile.s2 也可泛指为了击中目标而投出的物体。','雪球被投向目标。')],M('The report called the guided weapon a missile, then stated that it had no propulsion or means of reaching a target.','The report called the guided rocket a missile because it could steer toward its target.','无法移动或抵达目标的物体不符合导弹义。'),[Q('What did the missile do in the report?','It changed course toward a locked target.','It landed in a bowl of soup.','It became a stationary bridge.','missile.s1 指制导武器并飞向目标。'),Q('A snowball can be called a missile when it is?','thrown at a target','left untouched on the ground','melted into water','missile.s2 可指投掷物。'),Q('What does the guidance system help a missile do?','Steer toward its target.','Measure the weather.','Print a map label.','制导系统帮助导弹追踪目标。'),Q('The older Latin root is related to the idea of?','sending or throwing','remembering a song','being merciful','mittere 有发送、投出的意思。','word-formation')]);
P('missing','From miss plus -ing; as an adjective it means lost or absent when expected.',[C('missing.s1','人员失踪','Police issued an appeal for a missing hiker who had not returned from the trail by nightfall.','一名徒步者入夜后仍未从步道返回，警方发布寻人呼吁。','Police issued an appeal / for a missing hiker / who had not returned / from the trail by nightfall.','missing.s1 指人或物失踪、下落不明。','徒步者未按时归来且去向不明。'),C('missing.s2','部件缺失','The mechanic could not start the engine because a small but essential bolt was missing from the fuel pump.','燃油泵上缺少一颗虽小却关键的螺栓，修理工无法启动发动机。','The mechanic could not start the engine / because a small but essential bolt / was missing / from the fuel pump.','missing.s2 指应在某处但不在场或缺少的东西。','螺栓未在应有的位置。')],M('The mechanic found every bolt present, then reported that one bolt was missing from the fuel pump.','The mechanic found that the fuel pump was missing an essential bolt.','所有螺栓都在场却又说缺一颗，前后矛盾。'),[Q('Why did police seek the hiker?','The hiker had not returned and could not be located.','The hiker had checked in at the station.','The hiker had become a police officer.','missing.s1 表示失踪、下落不明。'),Q('What was missing from the fuel pump?','An essential bolt.','The mechanic’s entire workshop.','A signed poem.','missing.s2 表示部件缺少。'),Q('A missing person is someone who?','cannot be found and is unaccounted for','has arrived home safely','is present at a meeting','missing 可形容下落不明的人。'),Q('Which phrase uses missing correctly?','Two pages are missing from the report.','Two pages missingly the report.','The report is missing to two pages.','missing 可表示报告中缺了两页。','grammar')]);
P('mission','From Latin missio, “a sending,” from mittere, “to send”; it can mean an assigned task, a group sent on official work, a central purpose, or religious outreach.',[C('mission.s1','专项任务','The rescue team’s mission was to deliver clean water to villages cut off by the landslide.','救援队的任务是向被山体滑坡阻断交通的村庄运送干净饮水。','The rescue team’s mission / was to deliver clean water / to villages / cut off by the landslide.','mission.s1 指受托完成的重要任务或使命。','救援队被派去送水。'),C('mission.s2','外交使团','The trade mission met local officials to discuss new shipping agreements and customs procedures.','贸易代表团会见当地官员，讨论新的航运协议和海关程序。','The trade mission met local officials / to discuss new shipping agreements / and customs procedures.','mission.s2 可指被派往他国处理事务的一组人员。','代表团前往会谈官方事务。'),C('mission.s3','组织宗旨','The museum’s mission is to preserve regional history and make its archives accessible to local schools.','博物馆的宗旨是保存地区历史，并让当地学校能够使用档案。','The museum’s mission / is to preserve regional history / and make its archives / accessible to local schools.','mission.s3 指个人或组织的主要目的、宗旨。','保护历史并开放档案是博物馆宗旨。'),C('mission.s4','传教工作','The documentary follows a mission that runs a language school and a clinic in a remote mountain district.','这部纪录片记录了一个在偏远山区经营语言学校和诊所的传教活动。','The documentary follows / a mission / that runs a language school and a clinic / in a remote mountain district.','mission.s4 指宗教传播活动或从事该工作的场所、团体。','纪录片中的团体开展传教并提供服务。')],M('The museum stated its mission was preserving history, but then defined it as the weather forecast for next week.','The museum stated that its mission was to preserve regional history and share its archives.','机构宗旨应说明主要目的，不能与无关天气预报混同。'),[Q('What was the rescue team’s mission?','Delivering clean water to isolated villages.','Negotiating a shipping treaty.','Operating a religious school.','mission.s1 指受派任务。'),Q('Who took part in the trade mission?','A group sent to meet local officials.','A single missing hiker.','A group of museum visitors on holiday.','mission.s2 指出访处理官方事务的代表团。'),Q('The museum’s mission is its?','central purpose','building’s physical address','list of overdue invoices','mission.s3 表示组织宗旨。'),Q('A religious mission may be?','an organisation or activity that spreads a religion','a type of guided missile','a group sent to buy museum tickets','mission.s4 与宗教传播或相关团体有关。')]);
P('missionary','From mission plus -ary, through Latin missionarius; it refers to a person sent to spread a religion, or describes work related to such missions.',[C('missionary.s1','宗教人员','The missionary spent years learning the local language before teaching at the community school.','这位传教士花了多年学习当地语言，之后才在社区学校任教。','The missionary spent years / learning the local language / before teaching / at the community school.','missionary.s1 指被派去传播宗教信仰的人。','传教士学习当地语言后在当地开展工作。'),C('missionary.s2','传教相关','The archive preserves missionary letters describing the school and clinic established by the religious group.','档案保存着传教活动相关的信件，描述宗教团体建立的学校和诊所。','The archive preserves / missionary letters / describing the school and clinic / established by the religious group.','missionary.s2 作形容词，表示与传教活动有关。','信件记录传教团体所办机构。')],M('The historian called the nurse a missionary although she had no religious role and worked only as a local civil servant.','The historian described the teacher sent abroad to spread her faith as a missionary.','没有宗教传播角色的普通公务员不符合此处传教士义。'),[Q('The missionary learned the language in order to?','teach and work in the community','guide a missile to a target','measure the city’s mobility','missionary.s1 指被派去传播宗教的人。'),Q('Missionary letters are letters?','connected with religious mission work','written only by a medical machine','that cannot be read','missionary.s2 作形容词表示与传教相关。'),Q('What did the group establish?','A school and a clinic.','A shipping agreement.','A medieval castle only.','信件提到宗教团体建立学校和诊所。'),Q('Missionary is formed from mission plus?','-ary','-less','-dom','missionary 由 mission 加 -ary 构成。','word-formation')]);
P('misspend','From mis- “badly” and spend; it means to use money or time foolishly or for an unsuitable purpose.',C('misspend.s1','浪费资金','The agency misspent its grant on an extravagant launch party instead of the promised training programme.','机构没有把拨款用于承诺的培训项目，反而花在奢华的启动派对上。','The agency misspent its grant / on an extravagant launch party / instead of / the promised training programme.','misspend 是不规则动词，过去式和过去分词为 misspent；可指滥花钱或虚度时间。','拨款被花在无关的奢华派对上。'),M('The agency misspent the grant responsibly by funding exactly the training programme promised to donors.','The agency misspent the grant on a lavish party unrelated to its stated purpose.','按承诺用途负责任地使用资金不算滥花。'),[Q('How did the agency misspend the grant?','It used the money for an extravagant party.','It funded the promised training.','It returned every unused dollar.','misspend 指把钱花在不当用途。'),Q('To misspend time is to?','use it wastefully','save it for a later task','measure it accurately','misspend 也可表示虚度时间。'),Q('What is the past tense of misspend?','misspent','misspended','misspending','misspend 的过去式为 misspent。','verb-form'),Q('Which phrase is natural?','misspend public money','misspend to public money','misspendingly public money','misspend 直接接所浪费的时间或金钱。','grammar')]);
P('mist','From Old English mist, possibly with a Germanic source; it names a thin cloud of water droplets, a blur in the eyes, or the action of becoming or making unclear.',[C('mist.s1','近地薄雾','A light mist settled over the valley at dawn, softening the outlines of the houses across the river.','黎明时一层薄雾笼罩山谷，使河对岸房屋的轮廓变得柔和。','A light mist settled / over the valley / at dawn / softening the outlines of the houses across the river.','mist.s1 指近地面由细小水滴构成的薄雾。','薄雾遮淡了房屋轮廓。'),C('mist.s2','泪水模糊','A mist of tears blurred her vision as she listened to the farewell speech.','她听告别演讲时，泪水模糊了视线。','A mist of tears / blurred her vision / as she listened / to the farewell speech.','mist.s2 可指眼中泪水造成的模糊。','泪水影响了视线。'),C('mist.s3','玻璃起雾','The bathroom mirror began to mist after the hot shower, so he wiped a clear patch in the centre.','热水澡后浴室镜子开始起雾，他便在中央擦出一块清晰区域。','The bathroom mirror began to mist / after the hot shower / so he wiped / a clear patch in the centre.','mist.s3 作动词可表示起雾或使玻璃变模糊。','镜面因热蒸汽起雾。')],M('The mirror misted after the hot shower, yet it remained perfectly clear with no moisture or blur.','The mirror misted after the shower, so he wiped away the moisture.','既无水汽也不模糊，就不能说镜子起雾。'),[Q('What covered the valley at dawn?','A thin cloud of water droplets.','A thick layer of dry sand.','A fleet of boats.','mist.s1 指薄雾。'),Q('What blurred the speaker’s vision?','A mist of tears.','A cracked window.','A printed map.','mist.s2 指泪水造成的视线模糊。'),Q('The mirror began to mist means it?','became covered with moisture and less clear','was polished until spotless','fell off the wall','mist.s3 作动词指起雾。'),Q('Which phrase is natural?','a light mist over the valley','a mist of the valley by','the valley misted a light','薄雾可以说 a light mist over a place。','collocation')]);
P('mistake','From Old Norse mistaka, “take in error,” formed from mis- “wrongly” and taka, “take”; as a noun it is an error, and as a verb it means misunderstand or wrongly identify.',[C('mistake.s1','疏忽差错','Leaving the freezer door open overnight was a costly mistake because the stored samples thawed.','冰箱门整夜没关是个代价高昂的疏忽，储存的样本因此解冻。','Leaving the freezer door open overnight / was a costly mistake / because the stored samples / thawed.','mistake.s1 作名词指错误或做错的事。','门没关导致样本解冻，是一个差错。'),C('mistake.s2','弄错情况','I mistook the quiet room for an empty office and began speaking before noticing the meeting in progress.','我把安静的房间误以为是空办公室，开口后才注意到会议正在进行。','I mistook the quiet room / for an empty office / and began speaking / before noticing the meeting in progress.','mistake.s2 作动词可表示对事实或情形理解错误。','说话者误判了房间用途。'),C('mistake.s3','认错对象','In the dim light, I mistook my neighbour for a colleague and called him by the wrong name.','光线昏暗时，我把邻居认成同事，叫错了他的名字。','In the dim light / I mistook my neighbour / for a colleague / and called him by the wrong name.','mistake.s3 作动词可表示把一个人或物误认为另一个。','邻居被错认成同事。')],M('I mistook the neighbour for a colleague, but I recognised him correctly and used his name from the start.','I mistook the neighbour for a colleague and addressed him by the wrong name.','认对身份与把人错认成别人相矛盾。'),[Q('What was the costly mistake?','Leaving the freezer door open overnight.','Labelling every sample accurately.','Closing the door before leaving.','mistake.s1 指造成损失的差错。'),Q('The speaker mistook the quiet room for?','an empty office','a public train station','a hospital pharmacy','mistake.s2 指误判当时的情况。'),Q('Who did the speaker wrongly identify as a colleague?','A neighbour.','A pharmacist.','A meeting chair.','mistake.s3 指把邻居认成同事。'),Q('Which construction means “把A误认为B”?','mistake A for B','mistake A as B','mistake A to B','英语常用 mistake A for B。','grammar')]);
P('mistaken','Past participle of mistake; it means wrong or based on a misunderstanding.',C('mistaken.s1','错误判断','The team was mistaken in assuming that the old bridge could carry the heavier construction vehicles.','团队错误地以为这座旧桥能够承载更重的施工车辆。','The team was mistaken / in assuming / that the old bridge could carry / the heavier construction vehicles.','mistaken 作形容词，表示错误的或基于错误判断的。','桥梁承载能力的判断有误。'),M('The team was mistaken in its prediction, although every measurement and conclusion proved fully correct.','The team was mistaken because it ignored the bridge’s weight limit.','完全正确的结论与 mistaken 不符。'),[Q('What was the team mistaken about?','The old bridge’s ability to carry heavy vehicles.','The colour of the construction signs.','The route to the nearest café.','团队错误判断了桥梁承载能力。'),Q('Mistaken means?','wrong or based on a wrong idea','certainly correct','deliberately dishonest in every case','mistaken 表示错误，不一定是故意的。'),Q('Which phrase is natural?','be mistaken about the date','be mistaken to the date','mistakenly date about be','be mistaken about something 是自然搭配。','collocation'),Q('Mistaken is related to which verb?','mistake','melt','mend','mistaken 是 mistake 的过去分词形式。','word-formation')]);
P('mister','A variant of master used as the spoken title Mr, especially before a man’s surname.',C('mister.s1','口头称呼','“Mister Chen, the director is ready to see you,” the receptionist said as she opened the conference-room door.','接待员打开会议室门时说：“陈先生，主任已经准备好见您了。”','“Mister Chen / the director is ready to see you” / the receptionist said / as she opened the conference-room door.','mister 是 Mr 的口语形式，常放在男性姓氏前作称呼。','Mister Chen 用于姓氏前表示礼貌称呼。'),M('The receptionist addressed him as mister by placing the word after his surname: “Chen Mister.”','The receptionist addressed him as “Mister Chen,” using the title before his surname.','mister 应放在男性姓氏前，不能按 “Chen Mister” 排列。'),[Q('In the example, Mister Chen means?','Mr Chen, addressed politely','Chen’s medical diagnosis','a title after the man’s surname','mister 是 Mr 的口头称呼形式。'),Q('Where does Mister normally appear?','Before a man’s surname.','After a man’s surname.','Between a verb and its object only.','称呼置于姓氏前。'),Q('What did the receptionist announce?','The director was ready to meet Chen.','The conference room was missing.','A ferry had been cancelled.','接待员传达主任已准备好接见。'),Q('Mister is a spoken form of?','master','mystery','minister','mister 是 master 的语音变体。','word-formation')]);
P('mistreat','Formed from mis- “badly” and treat; it means to treat a person or animal badly or cruelly.',C('mistreat.s1','虐待动物','The shelter took in the dog after neighbours reported that its owner had mistreated it and left it without food.','邻居举报狗主人虐待它并不给食物后，收容所接收了这只狗。','The shelter took in the dog / after neighbours reported / that its owner had mistreated it / and left it without food.','mistreat 是及物动词，表示对人或动物施以恶劣、不公平或残忍的对待。','不给食物且虐待动物。'),M('The report said the owner mistreated the dog by feeding it regularly, taking it to a vet, and treating it gently.','The report said the owner mistreated the dog by withholding food and striking it.','定期喂养、就医并温柔对待不属于虐待。'),[Q('Why did the shelter take in the dog?','Its owner had mistreated and neglected it.','It had won a pet show.','Its neighbours wanted to adopt a different animal.','主人虐待并不给狗食物。'),Q('To mistreat someone is to?','treat them badly or cruelly','care for them generously','misunderstand their name once','mistreat 指恶劣或残忍对待。'),Q('Which action is mistreatment?','Withholding food from an animal in one’s care.','Taking an injured animal to a vet.','Providing clean water every day.','不给照料中的动物食物属于虐待。'),Q('Mistreat is formed from treat plus?','mis-','-ness','over-','mis- 表示错误或恶劣地对待。','word-formation')]);
P('mistress','From Old French maistresse, the feminine form of maistre (master), from Latin magister; it can mean a woman in charge, a woman in an extramarital relationship, or an older term for a female teacher.',[C('mistress.s1','女主人','The estate’s mistress welcomed the guests and showed them the rooms she had restored herself.','庄园女主人欢迎来宾，并带他们参观自己修复的房间。','The estate’s mistress welcomed the guests / and showed them / the rooms / she had restored herself.','mistress.s1 可指掌管家庭、住所或某项事务的女性。','她负责接待客人并管理庄园。'),C('mistress.s2','婚外伴侣','The novel reveals that the politician kept a mistress in another city, a secret that later caused a public scandal.','小说揭示这位政治家在另一座城市有一名情妇，这个秘密后来引发了公众丑闻。','The novel reveals / that the politician kept a mistress / in another city / a secret that later caused a public scandal.','mistress.s2 指与已婚男子保持性关系的女性，带有负面或旧式语域。','情节明确描述婚外关系。'),C('mistress.s3','旧式教师称谓','In the old school records, the headmistress assigned a senior mistress to teach Latin to the younger pupils.','旧校档案中，女校长安排一位资深女教师给低年级学生教拉丁语。','In the old school records / the headmistress assigned / a senior mistress / to teach Latin to the younger pupils.','mistress.s3 是旧式英式用法，指女教师。','该词出现在旧校档案和教学语境中。')],M('The school record used mistress for a male head teacher, although the entry explicitly identified him as a man.','The old school record called the female teacher a mistress, an older British term for a woman who taught.','该旧式义指女性教师，不适用于男性校长。'),[Q('Who welcomed guests at the estate?','The woman in charge of the household.','The male estate manager’s secretary.','A visiting pupil.','mistress.s1 可指女主人或女主管。'),Q('In the novel, the politician’s mistress was?','a woman with whom he had an extramarital relationship','his elected legal adviser','a school subject','mistress.s2 指婚外关系中的女性伴侣。'),Q('In older British school usage, a mistress could be?','a female teacher','a male student','a school timetable','mistress.s3 是旧式女教师称谓。'),Q('Which statement about mistress is accurate?','Its meaning depends on context and it can carry sensitive associations.','It always means a married woman’s official job title.','It is a neutral modern word for every teacher.','该词存在多种义项，且情妇义可能引起敏感联想。','register')]);
P('mistrust','Formed from mis- “badly” and trust; as a noun or verb it means lack of confidence in someone or something.',C('mistrust.s1','缺乏信任','Years of secret price changes created mistrust among customers, who no longer believed the company’s advertised discounts.','多年来秘密调整价格使顾客产生不信任，他们不再相信公司宣传的折扣。','Years of secret price changes / created mistrust among customers / who no longer believed / the company’s advertised discounts.','mistrust 可作名词指不信任，也可作动词表示不相信。','隐瞒价格变化损害顾客信任。'),M('Customers mistrusted the company because it published every price change openly and honoured every discount.','Customers mistrusted the company after hidden price changes made its discount claims unreliable.','公开价格变化并兑现折扣不会自然引发这种不信任。'),[Q('What created mistrust among customers?','Secret price changes.','A transparent list of all prices.','A reliable discount honoured at checkout.','隐瞒调价使顾客失去信任。'),Q('Mistrust means?','lack of confidence or trust','complete certainty','a written invitation','mistrust 指不信任。'),Q('Customers who mistrust an advertisement?','do not believe it readily','accept every claim without checking','write the advertisement themselves','mistrust 作动词表示不相信。'),Q('Which phrase is natural?','mistrust the company’s claims','mistrust about the company’s claims to','mistrust for believe the claims','mistrust 可直接接不信任的对象。','grammar')]);
P('misty','From mist plus -y; it means covered with mist, or unclear and indistinct as if seen through mist.',C('misty.s1','雾中景色','The coastal road was misty at sunrise, and the driver slowed down because the next bend was hard to see.','日出时海岸公路雾蒙蒙的，司机因看不清下一个弯道而减速。','The coastal road was misty / at sunrise / and the driver slowed down / because the next bend was hard to see.','misty 作形容词，可指被薄雾笼罩，也可比喻模糊不清。','雾遮挡视线，司机需要减速。'),M('The driver called the road misty even though the air was perfectly clear and every distant sign was sharp.','The driver called the road misty because fog obscured the next bend.','空气清澈且远处清晰时，不符合雾蒙蒙的描述。'),[Q('Why did the driver slow down?','Mist made the next bend hard to see.','The road had too many clear signs.','The car ran out of petrol.','雾影响能见度。'),Q('Misty can also describe a memory that is?','vague or indistinct','perfectly detailed','made of glass','misty 可比喻记忆模糊。'),Q('Misty is formed from mist plus?','-y','-age','-ful','mist 加 -y 构成形容词 misty。','word-formation'),Q('Which phrase is natural?','a misty morning','a mistily morning','a morning mistful','misty 可直接修饰 morning。','grammar')]);
P('misunderstand','Formed from mis- “wrongly” and understand; it means to fail to understand a meaning or to form an incorrect view of a situation.',[C('misunderstand.s1','误解意图','I misunderstood the email as a cancellation, but the organiser had only postponed the meeting by one hour.','我把邮件误解为取消活动，但组织者只是把会议推迟了一小时。','I misunderstood the email / as a cancellation / but the organiser had only postponed / the meeting by one hour.','misunderstand.s1 指没有正确理解表达的意思或意图。','邮件只说延期一小时，却被理解为取消。'),C('misunderstand.s2','判断事实有误','The witness misunderstood how the gate worked and wrongly assumed that it had been locked from the outside.','证人对大门的运作方式理解有误，错误地以为门是从外面锁上的。','The witness misunderstood / how the gate worked / and wrongly assumed / that it had been locked from the outside.','misunderstand.s2 也可指对事实情况形成错误理解。','证人对门锁机制判断错误。')],M('I misunderstood the email as a cancellation, although it explicitly said the meeting was only delayed by one hour.','I misunderstood the email as a cancellation and missed the rescheduled meeting.','仅延期一小时却当作取消，正是误解；反例不能说成正确理解。'),[Q('What did the organiser actually do?','Postponed the meeting by one hour.','Cancelled it permanently.','Moved it to a different country.','misunderstand.s1 这里指误解邮件内容。'),Q('What did the witness wrongly assume?','That the gate was locked from outside.','That the meeting had been cancelled.','That the gate was made of glass.','misunderstand.s2 指错误理解事实情况。'),Q('To misunderstand instructions is to?','fail to understand their intended meaning','follow them exactly','write them in another language correctly','misunderstand 表示没有正确理解。'),Q('Which construction is standard?','misunderstand someone’s intention','misunderstand about someone’s intention to','misunderstand for someone’s intention','misunderstand 后可直接接宾语。','grammar')]);
P('misunderstanding','Formed from misunderstand plus -ing; it means an incorrect understanding or a disagreement caused by one.',C('misunderstanding.s1','沟通误会','A misunderstanding about the deadline led two departments to prepare different versions of the same report.','对截止日期的误会导致两个部门准备了同一报告的不同版本。','A misunderstanding about the deadline / led two departments / to prepare different versions / of the same report.','misunderstanding 指错误理解，也可指由此产生的分歧。','双方理解了不同的截止时间。'),M('The departments had no misunderstanding because both read the deadline correctly and prepared the same report.','The departments had a misunderstanding about the deadline and prepared conflicting reports.','正确理解相同期限却准备同一报告，不是沟通误会。'),[Q('What caused the departments to prepare different reports?','A misunderstanding about the deadline.','A shortage of paper.','A cancelled training session.','错误理解截止时间造成报告不一致。'),Q('A misunderstanding can be?','an incorrect understanding or resulting disagreement','a perfect explanation','a signed employment contract','misunderstanding 可指误解或由此造成的分歧。'),Q('Which phrase is natural?','clear up a misunderstanding','clear up to a misunderstanding','make misunderstanding clear up it','常说 clear up a misunderstanding。','collocation'),Q('What word does misunderstanding come from?','misunderstand','mister','misdemeanor','misunderstanding 由 misunderstand 加 -ing 构成。','word-formation')]);
P('misuse','From mis- “wrongly” and use; it means using something incorrectly or excessively, or the act of doing so.',C('misuse.s1','药物滥用','The leaflet warns that misuse of the medicine, including taking extra doses, can cause serious side effects.','说明书警告，误用药物（包括额外服药）可能造成严重副作用。','The leaflet warns / that misuse of the medicine / including taking extra doses / can cause serious side effects.','misuse 作名词或动词，指不当或过度使用。','超剂量属于药物误用。'),M('The patient misused the medicine safely by following the prescribed dose exactly and asking before changing it.','The patient misused the medicine by taking several extra doses without medical advice.','严格遵守剂量并先咨询医生不是误用。'),[Q('Which action is misuse of medicine?','Taking extra doses without advice.','Following the prescribed dose.','Reading the patient leaflet.','超剂量服药属于药物误用。'),Q('Misuse can refer to?','wrong or excessive use','careful use as directed','a medication’s correct label','misuse 指不正确或过度使用。'),Q('What could medicine misuse cause?','Serious side effects.','An automatic cure with no risk.','A new bus route.','说明书提示误用会造成严重副作用。'),Q('Which phrase is grammatical?','misuse confidential information','misuse about confidential information','misuse to confidential information','misuse 可直接接被滥用的对象。','grammar')]);
P('mite','From Old English mite, a very small creature; the deeper origin is uncertain and may be connected with biting or smallness.',C('mite.s1','微小节肢动物','The vet found a mite under the dog’s fur and recommended treatment to stop the irritation from spreading.','兽医在狗毛下发现了一只螨虫，并建议治疗以免瘙痒扩散。','The vet found / a mite under the dog’s fur / and recommended treatment / to stop the irritation from spreading.','mite 指非常小的动物，常见如螨，有些会叮咬或引起刺激。','兽医在皮毛下发现了微小螨虫。'),M('The vet identified a mite as a large bird visible from across the room.','The vet identified a mite as a tiny creature found under the dog’s fur.','mite 是微小生物，不是大型远处可见的鸟。'),[Q('Where did the vet find the mite?','Under the dog’s fur.','Inside the medicine label.','On a distant mountain.','螨虫在狗毛下被发现。'),Q('A mite is generally?','a very small creature','a large sea mammal','a type of legal offence','mite 指微小生物。'),Q('Why was treatment recommended?','To prevent irritation from spreading.','To help the dog learn to read.','To repair a broken stair light.','兽医建议治疗以免刺激扩散。'),Q('What is known about the deeper origin of mite?','It is uncertain; a link to biting or smallness has been suggested.','It definitely comes from the word “moon.”','It was coined as a modern computer abbreviation.','该词的更深词源有不确定性。','usage')]);
P('mitigate','From Latin mitigare, “make mild or soften”; it means to make harm, risk, pain, conflict, or punishment less severe.',[C('mitigate.s1','风险减轻','Planting trees along the riverbank can mitigate flood damage by slowing runoff and stabilising the soil.','沿河岸种树可通过减缓地表径流、稳固土壤来减轻洪灾损失。','Planting trees along the riverbank / can mitigate flood damage / by slowing runoff / and stabilising the soil.','mitigate.s1 指使痛苦、损害或风险的严重程度降低。','植树能降低洪水造成的损害。'),C('mitigate.s2','冲突缓和','The mediator proposed a short pause to mitigate tensions before the two negotiating teams resumed talks.','调解员建议短暂停顿，以缓和紧张气氛，然后双方谈判团队再继续会谈。','The mediator proposed a short pause / to mitigate tensions / before the two negotiating teams / resumed talks.','mitigate.s2 可指缓和危机或冲突、减少紧张。','停顿有助于缓和谈判双方的紧张。')],M('The city mitigated flood damage by removing the riverbank trees and directing more runoff toward nearby homes.','The city mitigated flood damage by restoring wetlands that absorbed excess water.','加剧径流并增加房屋受灾风险不是减轻损害。'),[Q('How can trees mitigate flood damage?','By slowing runoff and stabilising soil.','By removing every riverbank plant.','By increasing rainfall directly.','mitigate.s1 指减轻洪水损害。'),Q('The mediator paused talks to mitigate?','tensions between the teams','the river’s water supply','a printed spelling error','mitigate.s2 指缓和紧张关系。'),Q('To mitigate a risk is to?','make it less serious','make it certain to happen','ignore it completely','mitigate 表示降低风险严重性。'),Q('Mitigate comes from a Latin verb meaning?','make mild or soften','send a message','take by mistake','拉丁语 mitigare 意为使缓和。','word-formation')]);
P('mitigation','From Latin mitigatio, from mitigare, “make mild or soften”; mitigation is an action or process that reduces harm, risk, severity, or punishment.',C('mitigation.s1','灾害减缓','The city’s flood-mitigation plan combines restored wetlands, warning systems, and stronger drainage channels.','该市的防洪减灾计划结合了湿地恢复、预警系统和更坚固的排水渠。','The city’s flood-mitigation plan / combines restored wetlands / warning systems / and stronger drainage channels.','mitigation 作名词，指减轻损害、风险或严重程度的措施与过程。','湿地、预警和排水设施共同降低洪灾风险。'),M('The report called the project flood mitigation even though it removed wetlands and increased the neighbourhood’s flood risk.','The report called the restored wetlands a flood-mitigation measure because they absorb excess water.','增加洪灾风险的做法不属于减灾。'),[Q('What does the city’s mitigation plan aim to do?','Reduce flood harm and risk.','Increase the damage caused by floods.','Replace every warning with a road sign.','mitigation 指减轻损害或风险的措施。'),Q('Which item is part of the plan?','Restored wetlands.','A new missile system.','A list of employee misdemeanors.','湿地恢复是计划中的措施。'),Q('Mitigation is related to which verb?','mitigate','misread','misbehave','mitigation 是 mitigate 的名词。','word-formation'),Q('Which phrase is natural?','risk mitigation','risk mitigationally','mitigation to the risk of by','risk mitigation 是常见组合。','collocation')]);
P('mitten','From Old French mitaine, “mitten”; the deeper origin is uncertain. A mitten covers the hand with one section for the fingers and a separate thumb.',C('mitten.s1','冬季手套','She wore a thick wool mitten on each hand, keeping her fingers together while leaving the thumb separate.','她两只手各戴一只厚羊毛连指手套，手指并在一处，拇指单独分开。','She wore / a thick wool mitten on each hand / keeping her fingers together / while leaving the thumb separate.','mitten 指手指共用一个套筒、拇指单独分开的手套。','例句描述了连指手套的典型结构。'),M('The shop labelled a glove with five separate finger compartments a mitten, even though each finger was fully separated.','The shop labelled the warm glove a mitten because four fingers shared one section and the thumb had its own.','五指完全分开的款式是普通手套，非连指结构。'),[Q('How are the fingers arranged in a mitten?','Four fingers share one section, with the thumb separate.','Each finger has a fully separate sleeve.','The thumb has no covering.','mitten 的四指部分共用一个套筒。'),Q('What material was the example mitten made from?','Wool.','Steel.','Paper.','例句说的是厚羊毛连指手套。'),Q('The deeper origin of mitten is?','uncertain','definitely Latin for “hand”','a recent computer abbreviation','该词更深词源尚不确定。'),Q('Which item is a mitten?','A winter hand covering with four fingers together.','A five-finger glove with separate compartments.','A shoe worn over the head.','连指结构是 mitten 的特征。')]);
P('mix','From Latin mixtus, the past participle of miscere, “to mix”; as a verb it means blend, confuse, or associate socially, and as a noun it means a combination.',[C('mix.s1','混合材料','Mix the flour and water slowly until the dough is smooth and no dry patches remain.','慢慢把面粉和水混合，直到面团光滑且没有干粉。','Mix the flour and water slowly / until the dough is smooth / and no dry patches / remain.','mix.s1 作动词，指把不同物质拌在一起。','面粉与水混合成面团。'),C('mix.s2','混淆对象','I always mix up the twins’ names because they look alike and answer to either one.','这对双胞胎长得相像，叫其中任意一个名字他们都会应声，所以我总把他们的名字弄混。','I always mix up the twins’ names / because they look alike / and answer / to either one.','mix.s2 指把两者混淆、弄错。','说话者分不清双胞胎的名字。'),C('mix.s3','社交往来','At the conference, new researchers mixed with experienced scientists during the informal reception.','会议的非正式招待会上，年轻研究人员与资深科学家交流往来。','At the conference / new researchers mixed with experienced scientists / during the informal reception.','mix.s3 作不及物动词，表示与人交往、相处。','不同资历的研究人员在招待会上交流。'),C('mix.s4','成分组合','The cake mix contains flour, dried fruit, and spices in a measured proportion.','蛋糕混合料按一定比例含有面粉、果干和香料。','The cake mix contains / flour, dried fruit, and spices / in a measured proportion.','mix.s4 作名词，指混合物或不同成分的组合。','包装食品是几种成分的混合料。')],M('The recipe says to mix flour and water, but the cook kept both ingredients separate and still called them mixed.','The cook mixed the flour and water until they formed a smooth dough.','材料保持分离就没有混合在一起。'),[Q('What should be mixed in the recipe?','Flour and water.','Two twins’ names.','Conference delegates.','mix.s1 表示把材料拌在一起。'),Q('To mix up the twins’ names means to?','confuse which name belongs to whom','blend the names into a cake','introduce both researchers','mix.s2 指混淆两个人的名字。'),Q('Researchers mixed with scientists at the reception means they?','socialised with them','confused their names','made a flour mixture','mix.s3 表示社交往来。'),Q('Cake mix is?','a prepared combination of ingredients','a verb meaning confuse','a type of meeting','mix.s4 作名词指混合料。')]);
P('mix up','A phrasal verb formed from mix plus up; it means to confuse two things or to stir ingredients together.',C('mix up.s1','混淆与拌匀','Please do not mix up the salt and sugar jars; after labelling them, mix up the batter until it is smooth.','请别把盐罐和糖罐弄混；贴好标签后，把面糊搅匀。','Please do not mix up the salt and sugar jars / after labelling them / mix up the batter / until it is smooth.','mix up 可指把两件事弄混，也可指搅拌均匀。','句子分别展示混淆物品和搅拌面糊两义。'),M('The cook mixed up the salt and sugar accurately by keeping each in its labelled jar and never confusing them.','The cook mixed up the salt and sugar jars, then corrected the labels before stirring the batter.','如果从未混淆，就不应说把盐糖弄混。'),[Q('“Mix up the salt and sugar jars” means?','Confuse which jar contains which ingredient.','Stir both closed jars together.','Throw the jars away.','mix up 可表示把两样东西弄混。'),Q('“Mix up the batter” means?','Stir it until blended.','Label it as sugar.','Leave it completely untouched.','mix up 也可表示搅拌均匀。'),Q('What should the cook do before mixing the batter?','Label the jars clearly.','Add another unlabeled ingredient.','Confuse salt with sugar.','例句先提醒标记容器以免混淆。'),Q('Mix up is a?','phrasal verb','plural noun','measurement symbol','mix up 由动词 mix 加小品词 up 构成。','grammar')]);
P('mixed','From Latin mixtus, the past participle of miscere, “to mix”; as an adjective it means consisting of different kinds or containing both positive and negative elements.',C('mixed.s1','多种成分','The mixed group included engineers, teachers, and health workers from six different towns.','这个混合小组由来自六个不同城镇的工程师、教师和医护人员组成。','The mixed group included / engineers, teachers, and health workers / from six different towns.','mixed.s1 描述由不同类型的人或物组成的整体。','小组包含多种职业和地区成员。'),M('The report called the team mixed although every member had the same job, training, and background.','The report called the team mixed because it included people from several professions and towns.','成员背景完全相同，不支持“多种构成”的描述。'),[Q('Why was the group mixed?','It included several professions and towns.','Every member had the same job and background.','It consisted only of one family.','mixed.s1 指由不同类型成员组成。'),Q('A mixed collection contains?','different kinds of items','only identical items','no items at all','mixed 表示不同类别混在一起。'),Q('Which expression often describes mixed feelings?','both positive and negative emotions','one perfectly clear emotion only','a measurement error','mixed feelings 常指复杂、好坏兼有的感受。'),Q('Mixed is the past participle of?','mix','mend','meet','mixed 是 mix 的过去分词。','word-formation')]);
P('mixture','From Latin mixtura, from miscere, “to mix”; it names things mixed together or the act or result of mixing.',C('mixture.s1','成分混合','The lab prepared a mixture of sand and salt, then used water to separate the soluble salt from the grains.','实验室配制了沙和盐的混合物，再用水把可溶的盐与沙粒分开。','The lab prepared / a mixture of sand and salt / then used water / to separate the soluble salt from the grains.','mixture 可指混合在一起的物质，也可指混合这一结果。','样品由沙与盐组成。'),M('The technician called a single pure sample a mixture although it contained only one substance.','The technician called the combined sand and salt a mixture because it contained two substances.','只含一种纯物质的样品不是混合物。'),[Q('What did the lab’s mixture contain?','Sand and salt.','Only pure water.','A collection of letters.','mixture.s1 指沙和盐混在一起的样品。'),Q('How did the lab separate the salt?','By dissolving it in water.','By freezing the sand into metal.','By printing new labels.','盐可溶于水，沙粒则可分离。'),Q('A mixture is?','a combination of substances or things','one pure substance only','a false belief about a chart','mixture 指不同成分的组合。'),Q('Mixture is related to which Latin verb?','miscere, “to mix”','mittere, “to send”','mirari, “to wonder”','mixture 与拉丁语“混合”相关。','word-formation')]);
P('mm','The SI symbol mm abbreviates millimetre (US: millimeter); the prefix m denotes milli-, one thousandth, and m denotes metre.',C('mm.s1','长度单位','The crack measured only 3 mm across, so the technician used a magnifier to inspect its edges.','裂缝宽度只有3毫米，因此技术人员用放大镜检查边缘。','The crack measured / only 3 mm across / so the technician used a magnifier / to inspect its edges.','mm 是 millimetre/millimeter 的国际单位制符号，等于0.001米。','裂缝以毫米计量。'),M('The technician recorded the crack as 3 mm but explained that mm meant three metres.','The technician recorded the crack as 3 mm, or three millimetres.','3 mm 是三毫米，不是三米。','measurement'),[Q('What does 3 mm mean?','Three millimetres.','Three metres.','Three minutes.','mm 是毫米的单位符号。'),Q('How many millimetres are in one metre?','1,000','10','100,000','一毫米是千分之一米。','measurement'),Q('Which is the correct SI symbol?','mm','MM','mms','毫米符号写作小写 mm。','capitalization'),Q('Why did the technician use a magnifier?','The crack was only a few millimetres wide.','The crack was three kilometres long.','The instrument was a mobile phone.','微小裂缝需要放大查看。')]);
P('moan','From Old English mænan, “complain or lament”; as a verb it means to make a long low sound or complain, and as a noun it names such a sound or complaint.',[C('moan.s1','痛苦呻吟','The injured cyclist moaned softly while the paramedics checked his leg and prepared a splint.','医护人员检查受伤的腿并准备夹板时，骑车人轻声呻吟。','The injured cyclist moaned softly / while the paramedics checked his leg / and prepared a splint.','moan.s1 作动词，指因疼痛等发出低沉、拖长的声音。','伤者因腿伤呻吟。'),C('moan.s2','抱怨工作','Several employees moaned about the schedule change because it added an unpaid weekend shift.','排班调整增加了一个无薪周末班，几名员工因此抱怨。','Several employees moaned / about the schedule change / because it added / an unpaid weekend shift.','moan.s2 作动词也表示发牢骚或抱怨。','员工抱怨新的排班要求。'),C('moan.s3','低声抱怨','A low moan came from the back row when the chair announced that the meeting would continue for another hour.','主席宣布会议还要继续一小时后，后排传来一声低低的抱怨。','A low moan came / from the back row / when the chair announced / that the meeting would continue for another hour.','moan.s3 作名词可指一声呻吟或抱怨声。','会场里出现一声表示不满的低叹。')],M('The cyclist moaned in relief while reporting that he felt no pain and made no sound.','The cyclist moaned softly because his injured leg hurt.','没有疼痛也没有发声就不符合呻吟义。'),[Q('Why did the cyclist moan?','His injured leg hurt.','He was pleased about an extra meeting.','He was trying to spell mobile.','moan.s1 指因疼痛发出低声。'),Q('Why did employees moan about the schedule?','It added an unpaid weekend shift.','It shortened every workday.','It included a paid holiday.','moan.s2 表示抱怨不利的排班变化。'),Q('What did the low moan express?','Displeasure at another hour of meeting.','Approval of the announcement.','A request for a medical dose.','moan.s3 是表示不满的低声抱怨。'),Q('Which preposition naturally follows moan in a complaint?','about','between of','along with to','常说 moan about a problem。','collocation')]);
P('moat','From Old French mote and Medieval Latin mota, “mound or fortified height,” with the sense shifting to the ditch around a castle; the deeper origin is uncertain.',[C('moat.s1','城堡防御','The stone castle stood behind a deep moat, which attackers could not cross without a bridge.','石堡后有一条深护城河，进攻者若没有桥就无法通过。','The stone castle stood / behind a deep moat / which attackers could not cross / without a bridge.','moat.s1 是围绕城堡或防御工事的壕沟，常注水作防御。','护城河阻挡进攻者。'),C('moat.s2','挖壕围护','The builders moated the small fort and reinforced the bank before the approaching army arrived.','军队到来前，建造者在小堡周围挖壕并加固土岸。','The builders moated the small fort / and reinforced the bank / before the approaching army arrived.','moat.s2 作动词，表示挖壕沟围绕某处。','堡垒被壕沟环绕。')],M('The fort was moated by filling its surrounding trench and removing every defensive ditch.','The builders moated the fort by digging a defensive trench around it.','填平壕沟并移除防御沟并非 moat。'),[Q('What protected the castle?','A deep defensive ditch.','A row of mobile phones.','A snowy road.','moat.s1 指城堡周围的防御壕沟。'),Q('The builders moated the fort means they?','dug a moat around it','built a roof over it','moved it to a new city','moat.s2 作动词表示以壕沟围绕。'),Q('Why could attackers not cross easily?','The deep moat blocked their approach.','The castle had no walls.','The bridge was permanently open.','深护城河需要桥梁才能通过。'),Q('What was the older sense related to?','A mound or fortified height.','A small insect bite.','A sound of complaint.','moat 的词源早期与土丘或高地有关。','word-formation')]);
P('mob','A shortening of mobile vulgus, Latin for “fickle common people”; it means an angry or disorderly crowd.',C('mob.s1','失控人群','Police formed a line to keep the angry mob away from the courthouse doors after the verdict.','判决宣布后，警方排成一列，阻止愤怒的人群靠近法院大门。','Police formed a line / to keep the angry mob / away from the courthouse doors / after the verdict.','mob 作名词指愤怒、混乱或有暴力倾向的一群人，语气强烈。','人群愤怒且需要警方控制。'),M('The report called the peaceful, orderly queue a mob although everyone waited quietly and followed directions.','The report called the angry crowd a mob after people pushed toward the courthouse.','安静守序的队列不符合 mob 的强烈贬义。'),[Q('Why did police form a line?','To keep an angry crowd from the courthouse doors.','To help a single visitor find a bus.','To start a parade in the town square.','mob 指愤怒或混乱的人群。'),Q('The word mob usually suggests a crowd that is?','disorderly or angry','quietly studying','small and carefully selected','mob 的语气常带混乱、愤怒意味。'),Q('Which crowd is most likely called a mob?','People pushing violently after a verdict.','A silent queue waiting in marked places.','A class listening to a lecture.','暴力推挤的群体符合 mob 的用法。'),Q('Mob was shortened from a Latin phrase meaning?','the fickle common people','a mobile telephone','a mild punishment','mob 来自 mobile vulgus 的缩写。','word-formation')]);
P('mobile','From Old French mobile and Latin mobilis, “movable,” from movere, “to move”; it can mean movable, quick to change, or a mobile telephone.',[C('mobile.s1','可移动设备','The mobile display stand can be wheeled between classrooms when teachers need extra space.','教师需要腾出空间时，这个可移动展示架可以推到不同教室。','The mobile display stand / can be wheeled / between classrooms / when teachers need extra space.','mobile.s1 作形容词，表示能够移动或不固定。','展示架可在教室之间推行。'),C('mobile.s2','面部表情','Her mobile face showed every change in mood as she listened to the surprising news.','听到令人惊讶的消息时，她那易变的表情显露出每一次情绪变化。','Her mobile face showed / every change in mood / as she listened / to the surprising news.','mobile.s2 可形容面部表情变化迅速、富于变化。','表情随着情绪不断变化。'),C('mobile.s3','便携电话','He checked the train platform on his mobile while walking to the station.','他走去车站时用手机查看列车站台信息。','He checked the train platform / on his mobile / while walking / to the station.','mobile.s3 作名词，尤其在英式英语中指移动电话。','他用手机查看站台。')],M('The display stand was described as mobile, but it was bolted permanently to the floor and could not move.','The display stand was mobile because staff could wheel it between rooms.','固定在地板上且无法移动，不符合可移动义。'),[Q('Why is the display stand mobile?','It can be wheeled between classrooms.','It changes its facial expression.','It is a telephone.','mobile.s1 指可移动的。'),Q('A mobile face is one that?','shows changing expressions','is attached to a telephone','cannot move at all','mobile.s2 指表情易变。'),Q('He checked the platform on his mobile means he used?','a portable phone','a mirror','a castle moat','mobile.s3 指手机。'),Q('Mobile ultimately relates to a Latin verb meaning?','to move','to remember','to soften','mobilis 来自 movere“移动”。','word-formation')]);
P('mobile phone','A compound of mobile and phone; mobile in this sense describes a telephone that connects to a wireless network and can be carried.',C('mobile phone.s1','无线通讯','When the train was delayed, Sam used his mobile phone to message his colleague and change their meeting time.','火车晚点时，山姆用手机给同事发消息，调整会面时间。','When the train was delayed / Sam used his mobile phone / to message his colleague / and change their meeting time.','mobile phone 指可随身携带、通过无线网络通信的电话。','设备用于移动中发送消息。'),M('Sam used a mobile phone by connecting a fixed desk handset to the wall and never carrying it anywhere.','Sam used a mobile phone to message his colleague while travelling.','固定桌机不是可随身携带的移动电话。'),[Q('What did Sam use the mobile phone for?','Messaging a colleague about a changed meeting time.','Measuring the train platform in millimetres.','Repairing the train’s engine.','手机用于发送消息和改约。'),Q('A mobile phone is designed to be?','carried and used on a wireless network','bolted permanently to a desk','operated only inside a castle','mobile phone 可随身携带并无线通信。'),Q('Why did Sam need to change the meeting time?','The train was delayed.','The colleague had moved overseas.','The phone had no screen.','列车晚点影响了会面安排。'),Q('Mobile phone is a compound of mobile and?','phone','moat','miser','该词由 mobile 与 phone 组成。','word-formation')]);
P('mobility','From Latin mobilitas, from mobilis, “movable”; it means the ability or opportunity to move physically, between places, or between social positions.',[C('mobility.s1','社会流动','The scholarship programme aims to improve social mobility by giving students from low-income families access to higher education.','奖学金计划旨在通过让低收入家庭学生接受高等教育来促进社会流动。','The scholarship programme aims / to improve social mobility / by giving students / from low-income families access to higher education.','mobility.s1 可指个人或群体在社会阶层间流动的机会。','教育机会帮助学生改变社会位置。'),C('mobility.s2','身体行动','After surgery, daily exercises gradually restored the patient’s mobility and ability to walk without support.','手术后，日常锻炼逐渐恢复了患者的行动能力，使其能够独立行走。','After surgery / daily exercises gradually restored / the patient’s mobility / and ability to walk without support.','mobility.s2 指身体或军队快速移动的能力。','患者逐渐恢复独立行走能力。')],M('The patient’s mobility improved when she became unable to move her legs or leave the bed.','The patient’s mobility improved as she regained the ability to walk without support.','失去行走能力与行动能力改善相反。'),[Q('How does the scholarship support social mobility?','It opens higher education to students from low-income families.','It moves students between hospital beds.','It provides a mobile phone to every professor.','mobility.s1 指社会阶层或位置的流动。'),Q('What improved after surgery?','The patient’s ability to move and walk.','The scholarship fund’s size.','The hospital’s phone signal.','mobility.s2 指身体行动能力。'),Q('Mobility can refer to movement?','between social levels or physically','only through a phone screen','only in a medieval period','该词含社会流动和身体行动两类义项。'),Q('Which phrase is natural?','social mobility','social mobilely','mobility of to society','social mobility 是常见组合。','collocation')]);
P('mobilize','From mobile plus -ize, ultimately from Latin mobilis, “movable”; it means to prepare forces for action or organize people to support a cause.',[C('mobilize.s1','军事动员','The government mobilized reserve troops after the border was attacked and moved them toward the affected region.','边境遭袭后，政府动员预备役部队并将其调往受影响地区。','The government mobilized reserve troops / after the border was attacked / and moved them / toward the affected region.','mobilize.s1 指使军队或人员做好行动准备。','预备役部队被调动以应对袭击。'),C('mobilize.s2','公众组织','Local residents mobilized volunteers to deliver food and blankets to families displaced by the storm.','当地居民组织志愿者，为因风暴流离失所的家庭送去食物和毯子。','Local residents mobilized volunteers / to deliver food and blankets / to families / displaced by the storm.','mobilize.s2 指组织人们采取行动或支持某项事业。','居民组织志愿者提供救助。')],M('The residents mobilized volunteers by telling everyone not to act, refusing to organize, and cancelling all aid deliveries.','The residents mobilized volunteers and coordinated deliveries of food and blankets.','阻止行动、取消救援与组织人手相反。'),[Q('Why did the government mobilize reserve troops?','The border was attacked.','A school opened a new library.','The storm passed without damage.','mobilize.s1 指动员部队应对袭击。'),Q('What did residents organize volunteers to deliver?','Food and blankets.','Court summonses.','Mobile phone bills.','mobilize.s2 指组织志愿者开展救助。'),Q('To mobilize a community is to?','organize people to act','make everyone immobile','confuse people’s names','mobilize 可指组织公众采取行动。'),Q('Mobilize is formed from mobile plus?','-ize','-less','-hood','-ize 构成表示使……或采取……行动的动词。','word-formation')]);
P('moccasin','From an Algonquian language of Virginia, probably Powhatan makasin, “shoe”; it names a soft leather shoe traditionally made by Indigenous North American peoples.',C('moccasin.s1','软皮鞋款','The museum displayed a pair of soft leather moccasins sewn by hand, with flexible soles and beadwork along the seams.','博物馆展出一双手工缝制的软皮莫卡辛鞋，鞋底柔软，接缝处有珠饰。','The museum displayed / a pair of soft leather moccasins / sewn by hand / with flexible soles and beadwork along the seams.','moccasin 指一种柔软皮革鞋，传统上与北美原住民服饰有关。','展品是软皮、手缝鞋。'),M('The catalogue called a rigid metal hiking boot a moccasin, although it had a stiff shell and no soft leather.','The catalogue called the flexible hand-sewn leather shoes moccasins.','硬质金属靴不符合软皮鞋的典型特征。'),[Q('What material were the museum moccasins made from?','Soft leather.','Metal mesh.','Woven paper.','moccasin 通常是软皮鞋。'),Q('What feature did the shoes have?','Flexible soles and beadwork.','Rigid metal shells.','A built-in phone screen.','展品鞋底柔软并有珠饰。'),Q('The word moccasin probably comes from?','Powhatan makasin, “shoe”','Latin movere, “move”','Old French mocquer, “mock”','词源可能来自波瓦坦语 makasin，意为鞋。','word-formation'),Q('Which origin statement is appropriately cautious?','It probably came from a Virginia Algonquian language.','Its exact root is certainly Latin.','It was invented as a recent brand name.','词源资料把 Powhatan 来源标为可能而非确定。','usage')]);
P('mock','From Old French mocquer, “deride”; the verb means to ridicule or imitate, the adjective means simulated or counterfeit, and the noun can name ridicule or its target.',[C('mock.s1','嘲弄同学','The classmates mocked his accent until the teacher stopped the lesson and asked them to apologise.','同学们嘲笑他的口音，老师只得停下课程并要求他们道歉。','The classmates mocked his accent / until the teacher stopped the lesson / and asked them / to apologise.','mock.s1 作动词，指以轻蔑或刻薄方式嘲笑某人。','同学嘲笑口音，表现贬损行为。'),C('mock.s2','模拟演练','The hospital ran a mock emergency drill so staff could practise evacuating patients without putting anyone at risk.','医院进行了一次模拟紧急演练，让员工练习疏散病人而不使任何人处于危险中。','The hospital ran / a mock emergency drill / so staff could practise evacuating patients / without putting anyone at risk.','mock.s2 作形容词，表示模拟的、非真实但仿照真实情境的。','演练模拟紧急情况但没有真实危险。'),C('mock.s3','嘲笑对象','The flimsy stage set became a mock of the grand palace it was supposed to represent.','这个摇摇欲坠的舞台布景成了它原本要表现的宏伟宫殿的可笑仿制品。','The flimsy stage set became / a mock of the grand palace / it was supposed to represent.','mock.s3 作名词可指嘲弄行为或可笑的仿制品。','布景与宏伟宫殿差距很大，成了拙劣仿制。')],M('The students mocked their classmate by praising his accent sincerely and asking others to learn from it.','The students mocked their classmate by imitating his accent to make him look foolish.','真诚赞赏并鼓励学习不是嘲弄。'),[Q('How did the classmates mock him?','They ridiculed his accent.','They helped him practise a speech.','They ran an emergency drill.','mock.s1 指刻薄地嘲笑。'),Q('A mock emergency drill is?','a practice simulation, not a real emergency','an actual disaster with injured patients','a joke about a hospital','mock.s2 表示模拟的演练。'),Q('The flimsy set became a mock of the palace means it was?','a poor or ridiculous imitation','the genuine royal residence','a fully accurate blueprint','mock.s3 指可笑或拙劣的仿制品。'),Q('Which preposition naturally follows mock when naming a target?','mock someone for something','mock someone by at something','mock someone with about','常说 mock someone for an accent or mistake。','collocation')]);
P('mocker','From mock plus the agent suffix -er; it means a person who ridicules or imitates someone scornfully.',C('mocker.s1','嘲笑者','The mocker repeated the speaker’s stutter to embarrass him, and the audience fell silent.','嘲笑者重复模仿演讲者的口吃来让他难堪，听众顿时安静下来。','The mocker repeated the speaker’s stutter / to embarrass him / and the audience / fell silent.','mocker 指嘲笑或讥讽他人的人。','重复模仿口吃意在让人难堪。'),M('The report described the considerate listener who stopped the jokes as a mocker.','The report described the person who imitated the speaker’s stutter to embarrass him as a mocker.','制止嘲笑的人并非嘲笑者。'),[Q('What did the mocker do?','Repeated the speaker’s stutter to embarrass him.','Helped the speaker finish his talk.','Organised a mobile phone repair.','mocker 指实施嘲笑的人。'),Q('A mocker is a person who?','ridicules or imitates others scornfully','safely operates a moat','measures a small crack','mocker 是嘲笑者。'),Q('Which word is the base of mocker?','mock','mend','melt','mocker 由 mock 加 -er 构成。','word-formation'),Q('What happened to the audience?','They fell silent.','They laughed at the speaker together.','They left for the airport.','听众在难堪的嘲笑后安静下来。')]);
P('mockery','From mock plus -ery; it means the act of mocking, or a person or thing treated as an absurd imitation.',C('mockery.s1','讥笑行为','The review called the imitation of the mayor’s speech cruel mockery rather than harmless satire.','评论认为模仿市长讲话是残酷的嘲弄，而非无伤大雅的讽刺。','The review called / the imitation of the mayor’s speech / cruel mockery / rather than harmless satire.','mockery 指嘲笑、讥讽的行为，也可指可笑的仿制。','评论区分伤人的嘲弄与温和讽刺。'),M('The report called the accurate, respectful portrait of the mayor mockery although it contained no joke or imitation.','The report called the deliberately distorted impersonation of the mayor mockery.','准确尊重的肖像不是嘲笑性模仿。'),[Q('What did the review call cruel mockery?','An imitation of the mayor’s speech.','A factual transcript of the speech.','A polite thank-you note.','mockery 指带嘲弄意味的模仿行为。'),Q('Mockery can mean?','ridicule or an absurd imitation','a sincere compliment only','a medical dose','mockery 指嘲笑，也可指拙劣仿制。'),Q('Which phrase is natural?','be the object of mockery','be the object to mockery of','be mockingery object','常说 be the object of mockery。','collocation'),Q('Mockery is related to which verb?','mock','mobilize','mistreat','mockery 由 mock 派生。','word-formation')]);
P('mocking','From the present participle of mock; as an adjective it describes a scornful or derisive tone, expression, or imitation.',C('mocking.s1','讥讽语气','“That was a brilliant idea,” she said in a mocking voice after the plan failed for the third time.','计划第三次失败后，她用讥讽的语气说：“真是个绝妙的主意。”','“That was a brilliant idea” / she said / in a mocking voice / after the plan failed for the third time.','mocking 作形容词，表示嘲弄、轻蔑的。','失败后反话式赞扬显示讥讽。'),M('She used a mocking tone to express sincere admiration, and nobody could detect any ridicule.','She used a mocking tone to ridicule the plan after it failed repeatedly.','完全真诚且没有嘲弄意图的语气不能称作 mocking。'),[Q('Why was her voice mocking?','She was ridiculing a plan that had failed repeatedly.','She was praising the plan with sincere admiration.','She was reading a medical report neutrally.','mocking 表示讥讽、嘲弄的语气。'),Q('A mocking expression usually shows?','scorn or ridicule','fear of a storm only','a lack of any emotion','mocking 的表情带有嘲弄意味。'),Q('Mocking is the -ing form of?','mock','mist','merit','mocking 是 mock 的现在分词形式。','word-formation'),Q('Which phrase is natural?','a mocking smile','a mockingly smile','a smile mocking of','mocking 可作形容词修饰 smile。','grammar')]);
P('mockingbird','A compound of mocking, from mock, and bird; the name reflects the bird’s notable ability to imitate the calls of other birds and sounds.',C('mockingbird.s1','仿声鸟类','At dusk, the mockingbird copied the calls of several neighbouring species from the telephone wire above the garden.','黄昏时，嘲鸫在花园上方的电话线上模仿了几种邻近鸟类的叫声。','At dusk / the mockingbird copied the calls / of several neighbouring species / from the telephone wire above the garden.','mockingbird 是一种以模仿其他鸟类鸣声闻名的鸟。','它模仿附近鸟类的叫声。'),M('The guide called the bird a mockingbird, then said it never copied sounds and could not sing.','The guide called it a mockingbird because it imitated calls heard nearby.','模仿鸣叫是 mockingbird 名称所关联的显著特征。'),[Q('What did the mockingbird imitate?','Calls of neighbouring bird species.','The shape of a castle moat.','The spelling of a phone number.','mockingbird 以模仿其他鸟的叫声闻名。'),Q('Where was the bird perched?','On a telephone wire above the garden.','Inside the train station.','Under a flooded bridge.','例句中鸟在花园上方的电话线上。'),Q('The name mockingbird combines mocking and?','bird','merit','mistrust','该复合词由 mocking 和 bird 构成。','word-formation'),Q('Which behaviour is most characteristic of this bird?','Imitating other birds’ calls.','Building a moat around its nest.','Using a mobile phone.','嘲鸫的特点之一是模仿鸣声。')]);

})();
